1	"use client";
2	
3	import { useCallback, useEffect, useRef, useState } from "react";
4	import {
5	  IconUpload, IconFileText, IconCircleCheck, IconAlertTriangle, IconClockHour4,
6	  IconChevronRight, IconTrash, IconCalendar, IconExternalLink, IconArrowUpRight, IconArticle,
7	  IconArrowsExchange, IconArchive, IconArrowBackUp, IconTrashX,
8	} from "@tabler/icons-react";
9	import { typeIcon } from "./fileIcons";
10	import ModelSelect from "./ModelSelect";
11	
12	function SourceGroup({ ym, items, onArchive, onWiki, onRecover, onRestore, onPurge, deleting, acting, notes, canManage, archivedMode }: {
13	  ym: string; items: SourceItem[]; onArchive: (s: SourceItem) => void; onWiki: (s: SourceItem) => void;
14	  onRecover: (s: SourceItem) => void; onRestore?: (s: SourceItem) => void; onPurge?: (s: SourceItem) => void;
15	  deleting: number | null; acting: Set<number>; notes: Record<number, string>; canManage: boolean; archivedMode?: boolean;
16	}) {
17	  const [open, setOpen] = useState(true);
18	  return (
19	    <div>
20	      <button className="mat-group" onClick={() => setOpen((o) => !o)}>
21	        <IconChevronRight size={13} className={`tree-caret${open ? " open" : ""}`} />
22	        <IconCalendar size={14} />{ym}<span className="mat-group-count">({items.length})</span>
23	      </button>
24	      {open && items.map((s) => {
25	        const FIcon = typeIcon(s.type);
26	        // 정상 흐름은 업로드 박스에서 처리됨. 여기 PENDING/FAILED는 업로드 중 이탈 등으로 남은 '잔여' → 재처리 복구만.
27	        const stuck = s.status === "PENDING" || s.status === "FAILED";
28	        const busy = acting.has(s.id);
29	        const note = notes[s.id];
30	        return (
31	          <div key={s.id} className="mat-item tree">
32	            <FIcon size={17} className="mat-ficon" />
33	            <div className="mat-item-main">
34	              <div className="mat-item-title" title={s.title}>{s.title}</div>
35	              <div className="mat-item-sub"><span className="mat-ext">{s.type}</span> · {s.createdAt.slice(0, 10)}</div>
36	              {note && <div className="mat-item-note">{note}</div>}
37	            </div>
38	            {!archivedMode && (
39	              <span className={`mat-status ${s.status === "APPLIED" ? "ok" : s.status === "FAILED" ? "err" : s.status === "UNANALYZED" ? "warn" : s.status === "PENDING" ? "pend" : "muted"}`}>
40	                {busy ? "처리 중…" : s.status === "APPLIED" ? "반영됨" : s.status === "FAILED" ? "실패" : s.status === "SKIPPED_DUP" ? "중복" : s.status === "UNANALYZED" ? "미분석" : s.status === "PENDING" ? "분석 대기" : s.status ?? "-"}
41	              </span>
42	            )}
43	            <div className="mat-acts">
44	              <a className="mat-act" href={`/api/materials/${s.id}/raw`} target="_blank" rel="noreferrer" title="원본 열기"><IconExternalLink size={13} /></a>
45	              {archivedMode ? (
46	                <>
47	                  <button className="mat-act" disabled={busy} onClick={() => onRestore!(s)} title="복원"><IconArrowBackUp size={14} /></button>
48	                  <button className="mat-del" disabled={deleting === s.id || busy} onClick={() => onPurge!(s)} title="영구삭제"><IconTrashX size={14} /></button>
49	                </>
50	              ) : (
51	                <>
52	                  {stuck && !busy && <button className="mat-run" onClick={() => onRecover(s)} title="이 자료를 (위쪽에서 고른 방식으로) 다시 처리">재처리</button>}
53	                  {!stuck && <button className="mat-act" onClick={() => onWiki(s)} title="위키 페이지로 이동"><IconArrowUpRight size={13} /></button>}
54	                  {s.hasExtracted && (
55	                    <a className="mat-act" href={`/api/materials/${s.id}/extracted`} target="_blank" rel="noreferrer" title="추출본(읽은 텍스트)"><IconArticle size={13} /></a>
56	                  )}
57	                  {canManage && <button className="mat-del" disabled={deleting === s.id || busy} onClick={() => onArchive(s)} title="아카이브(삭제)"><IconTrash size={13} /></button>}
58	                </>
59	              )}
60	            </div>
61	          </div>
62	        );
63	      })}
64	    </div>
65	  );
66	}
67	
68	interface SourceItem { id: number; title: string; type: string; createdAt: string; status: string | null; confidence: number | null; gate: string | null; extractStatus?: string | null; extractor?: string | null; hasExtracted?: boolean; hasText?: boolean; looksOrganized?: boolean; archived?: boolean }
69	interface UFile { id: number; name: string; status: "pending" | "running" | "done" | "error"; note?: string }
70	interface UploadPolicy { provider: string; tier?: string; textOnly: boolean; vision?: boolean; exts: string[]; accept: string; note: string }
71	// 모델 id를 짧고 읽기 쉽게(공급자 접두·버전 접미 제거).
72	function shortModel(id?: string): string {
73	  if (!id) return "";
74	  return (id.split("/").pop() || id).replace(/-17b-16e-instruct|-versatile|-instruct/g, "");
75	}
76	interface ModelOpt { id: string; label: string; provider: string; enabled: boolean; note?: string; kind?: "primary" | "backup"; backupOf?: string }
77	
78	// 문서 업로드는 큰 컨텍스트가 필요 — Groq 소형-TPM 모델(gpt-oss-120b 등 8K/분)은 문서 한 개도 못 담아 폴백한다.
79	// llama-3.3(12K)·Gemini·Claude·로컬(ollama)은 'doc-ok'. lib/query.ts ctxBudgetFor와 같은 기준(llama-3.3만 큰 쪽).
80	function isSmallCtxModel(m?: ModelOpt): boolean {
81	  return !!m && m.provider === "openai-compat" && !/llama-3\.3-70b/i.test(m.id);
82	}
83	// 선택 모델이 소형-TPM이면, 그 모델의 백업(폴백 순서) 중 첫 'doc-ok·활성'으로 자동 전환. 없으면 그대로(백엔드 폴백이 처리).
84	function docModelFor(selectedId: string, models: ModelOpt[]): string {
85	  const sel = models.find((m) => m.id === selectedId);
86	  if (!sel || !isSmallCtxModel(sel)) return selectedId;
87	  const alt = models.find((m) => m.backupOf === selectedId && m.enabled && !isSmallCtxModel(m));
88	  return alt?.id ?? selectedId;
89	}
90	
91	// 업로드 원본을 연-월(YYYY-MM)로 묶어 최신순 트리로.
92	function groupByMonth(sources: SourceItem[]): [string, SourceItem[]][] {
93	  const m = new Map<string, SourceItem[]>();
94	  for (const s of sources) {
95	    const k = s.createdAt.slice(0, 7);
96	    const arr = m.get(k);
97	    if (arr) arr.push(s); else m.set(k, [s]);
98	  }
99	  return [...m.entries()].sort((a, b) => b[0].localeCompare(a[0]));
100	}
101	
102	export default function MaterialsTab({ scope, onOpenWiki, modelsRev }: { scope: string; onOpenWiki: (path: string) => void; modelsRev?: number }) {
103	  const [title, setTitle] = useState("");
104	  const [text, setText] = useState("");
105	  const [busy, setBusy] = useState(false);
106	  const [err, setErr] = useState<string | null>(null);
107	  const [result, setResult] = useState<{ ok: boolean; note: string } | null>(null);
108	  const [uploadMode, setUploadMode] = useState<"llm" | "raw">("llm"); // 업로드 박스에서 미리 고르는 처리 모드
109	  const [sources, setSources] = useState<SourceItem[]>([]);
110	  const [deleting, setDeleting] = useState<number | null>(null);
111	  const [delNote, setDelNote] = useState<string | null>(null);
112	  const [canManage, setCanManage] = useState(false); // 아카이브·영구삭제 권한(룸 관리자)
113	  const [archivedSources, setArchivedSources] = useState<SourceItem[]>([]);
114	  const [showArchived, setShowArchived] = useState(false);
115	  const [convertExts, setConvertExts] = useState<string[]>([]);
116	  const [policy, setPolicy] = useState<UploadPolicy | null>(null);
117	  const [models, setModels] = useState<ModelOpt[]>([]);
118	  const [model, setModel] = useState<string>("");
119	  const [policies, setPolicies] = useState<Record<string, UploadPolicy>>({});
120	  const [queue, setQueue] = useState<UFile[]>([]);
121	  const [dragOver, setDragOver] = useState(false);
122	  const [acting, setActing] = useState<Set<number>>(new Set()); // 분석/원본그대로 처리 중인 소스 id
123	  const [notes, setNotes] = useState<Record<number, string>>({}); // 처리 결과 메모(자동전환·반영 등)
124	  const fileRef = useRef<HTMLInputElement>(null);
125	
126	  const load = useCallback(async () => {
127	    try {
128	      const res = await fetch(`/api/materials?scope=${encodeURIComponent(scope)}`, { cache: "no-store" });
129	      const d = await res.json();
130	      if (res.ok) {
131	        setSources(d.sources); setConvertExts(d.convertExts || []); setPolicy(d.policy || null);
132	        setCanManage(Boolean(d.canManage));
133	        setModels(d.models || []); setPolicies(d.policies || {});
134	        setModel((cur) => {
135	          const ms: ModelOpt[] = d.models || [];
136	          if (cur && ms.some((m) => m.id === cur && m.enabled)) return cur; // 현재 선택이 여전히 유효하면 유지
137	          const def = d.defaultModel && ms.some((m) => m.id === d.defaultModel && m.enabled) ? d.defaultModel : null;
138	          return def || ms.find((m) => m.enabled)?.id || "";
139	        });
140	      }
141	    } catch { /* noop */ }
142	  }, [scope]);
143	
144	  // 아카이브된 자료 목록(복원/영구삭제 뷰) — 별도 조회(?archived=1).
145	  const loadArchived = useCallback(async () => {
146	    try {
147	      const res = await fetch(`/api/materials?scope=${encodeURIComponent(scope)}&archived=1`, { cache: "no-store" });
148	      const d = await res.json();
149	      if (res.ok) setArchivedSources(d.sources || []);
150	    } catch { /* noop */ }
151	  }, [scope]);
152	
153	  // 선택한 인제스트 모델의 공급자에 맞는 업로드 정책(없으면 서버 기본 policy).
154	  const curProvider = models.find((m) => m.id === model)?.provider;
155	  // ★모델 id별★ 정책 — 같은 Groq라도 모델(비전 유무)에 따라 허용 확장자·안내가 달라진다.
156	  const curPol = policies[model] || policy;
157	  // ★문서 자동 전환★: 소형-TPM 모델(gpt-oss-120b 등)을 고르면 업로드는 doc-ok 모델로 보낸다
158	  //   (불필요한 413 왕복 제거 + 어느 모델이 처리하는지 예측 가능). switchedTo 있으면 셀렉터에 안내.
159	  const uploadModel = docModelFor(model, models);
160	  const switchedTo = uploadModel !== model ? models.find((m) => m.id === uploadModel) : null;
161	
162	  useEffect(() => { setSources([]); setResult(null); setErr(null); setDelNote(null); setArchivedSources([]); setShowArchived(false); load(); }, [scope, load]);
163	  // 관리자가 설정에서 모델 토글 후 모달을 닫으면(modelsRev 변경) 모델·정책을 다시 불러온다.
164	  useEffect(() => { if (modelsRev !== undefined) load(); }, [modelsRev, load]);
165	
166	  async function openWiki(s: SourceItem) {
167	    try {
168	      const res = await fetch(`/api/materials/${s.id}/pages`);
169	      const d = await res.json();
170	      if (res.ok && d.paths?.length) onOpenWiki(d.paths[0]);
171	      else setDelNote(`「${s.title}」에서 생성된 위키 페이지를 찾지 못했습니다.`);
172	    } catch {
173	      setDelNote("위키 페이지를 찾지 못했습니다.");
174	    }
175	  }
176	
177	  // 자료 아카이브(소프트 삭제) — 목록에서 숨기고 아카이브로. 원본·위키 페이지는 보존. 룸 관리자만.
178	  async function archiveSource(s: SourceItem) {
179	    if (!confirm(`원본 「${s.title}」을(를) 아카이브할까요?\n목록에서 숨겨지며, 아카이브에서 복원하거나 영구삭제할 수 있습니다. (위키 페이지는 그대로 유지됩니다)`)) return;
180	    setDeleting(s.id); setDelNote(null);
181	    try {
182	      const res = await fetch(`/api/materials/${s.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "archive" }) });
183	      const d = await res.json();
184	      if (!res.ok) throw new Error(d.error || "아카이브에 실패했습니다.");
185	      setDelNote(`「${s.title}」 아카이브됨`);
186	      await Promise.all([load(), loadArchived()]);
187	    } catch (e) {
188	      setDelNote(`오류: ${e instanceof Error ? e.message : String(e)}`);
189	    } finally {
190	      setDeleting(null);
191	    }
192	  }
193	
194	  // 아카이브에서 복원 — 다시 활성 목록으로.
195	  async function restoreSource(s: SourceItem) {
196	    setDeleting(s.id); setDelNote(null);
197	    try {
198	      const res = await fetch(`/api/materials/${s.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "restore" }) });
199	      const d = await res.json();
200	      if (!res.ok) throw new Error(d.error || "복원에 실패했습니다.");
201	      setDelNote(`「${s.title}」 복원됨`);
202	      await Promise.all([load(), loadArchived()]);
203	    } catch (e) {
204	      setDelNote(`오류: ${e instanceof Error ? e.message : String(e)}`);
205	    } finally {
206	      setDeleting(null);
207	    }
208	  }
209	
210	  // 영구삭제 — 원본·사이드카 제거 + 인용 위키 페이지에 '출처 소실' 표시. 되돌릴 수 없음.
211	  async function purgeSource(s: SourceItem) {
212	    if (!confirm(`원본 「${s.title}」을(를) 영구삭제할까요? 되돌릴 수 없습니다.\n매핑된 위키 페이지는 보존되며 '출처 소실' 표시가 남습니다.`)) return;
213	    setDeleting(s.id); setDelNote(null);
214	    try {
215	      const res = await fetch(`/api/materials/${s.id}`, { method: "DELETE" });
216	      const d = await res.json();
217	      if (!res.ok) throw new Error(d.error || "삭제에 실패했습니다.");
218	      setDelNote(`「${s.title}」 영구삭제됨 · 위키 ${d.annotated}곳에 출처 소실 표시`);
219	      await Promise.all([load(), loadArchived()]);
220	    } catch (e) {
221	      setDelNote(`오류: ${e instanceof Error ? e.message : String(e)}`);
222	    } finally {
223	      setDeleting(null);
224	    }
225	  }
226	
227	  // 파일 선택/드롭 → 모두 서버 업로드 큐로(여러 개 가능). 수동 입력은 아래 textarea를 쓴다.
228	  function onPickFile(e: React.ChangeEvent<HTMLInputElement>) {
229	    const files = e.target.files ? [...e.target.files] : [];
230	    e.target.value = "";
231	    if (files.length) void uploadMany(files);
232	  }
233	
234	  function onDrop(e: React.DragEvent) {
235	    e.preventDefault();
236	    setDragOver(false);
237	    const files = e.dataTransfer?.files ? [...e.dataTransfer.files] : [];
238	    if (files.length) void uploadMany(files);
239	  }
240	
241	  // 스테이징된 소스를 ★업로드 박스에서 고른 모드★로 처리(클라 체이닝). raw는 텍스트가 있을 때만,
242	  // 없으면(PDF·이미지 등) 자동으로 llm. 결과 메모는 처리 후 소스 id(llm은 dedup으로 바뀜)에 단다.
243	  async function runProcess(sourceId: number, hasText: boolean): Promise<{ ok: boolean; note: string; newId: number }> {
244	    const fellBack = uploadMode === "raw" && !hasText;
245	    const effMode = uploadMode === "raw" && hasText ? "raw" : "llm";
246	    const body = effMode === "raw" ? { mode: "raw" } : { mode: "llm", model: docModelFor(model, models) };
247	    const res = await fetch(`/api/materials/${sourceId}/analyze`, {
248	      method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body),
249	    });
250	    const data = await res.json();
251	    if (!res.ok) return { ok: false, note: `처리 실패: ${data.error || ""}`, newId: sourceId };
252	    const newId: number = data.sourceId ?? sourceId;
253	    if (effMode === "raw") return { ok: true, note: "원본 그대로 추가됨 · 토큰 0", newId };
254	    const served: string | undefined = data.usedModel;
255	    const sw = served && served !== model ? ` · ${shortModel(model)}→${shortModel(served)} 자동전환` : "";
256	    const prefix = fellBack ? "텍스트 없음 → 분석함 · " : "";
257	    const base = data.status === "NEEDS_REVIEW" ? "검토 대기" : "분석 반영됨";
258	    return { ok: true, note: prefix + base + sw, newId };
259	  }
260	
261	  // 한 파일: 스테이징 → 곧바로 선택 모드로 처리(체이닝). 사용자에겐 한 단계로 보인다.
262	  async function uploadOne(f: File, withTitle?: string): Promise<{ ok: boolean; note: string }> {
263	    try {
264	      const fd = new FormData();
265	      fd.append("scope", scope);
266	      if (withTitle) fd.append("title", withTitle);
267	      if (model) fd.append("model", model); // 업로드 정책 게이팅용(허용 확장자)
268	      fd.append("file", f);
269	      const res = await fetch("/api/materials", { method: "POST", body: fd });
270	      const data = await res.json();
271	      if (!res.ok) return { ok: false, note: data.error || "업로드 실패" };
272	      if (data.status === "SKIPPED_DUP") return { ok: true, note: "중복(건너뜀)" };
273	      if (data.unanalyzed || !data.sourceId) return { ok: true, note: "원본 보존(미분석)" };
274	      const r = await runProcess(data.sourceId, !!data.hasText);
275	      return { ok: r.ok, note: r.note };
276	    } catch (e) {
277	      return { ok: false, note: e instanceof Error ? e.message : String(e) };
278	    }
279	  }
280	
281	  // 여러 파일을 '순차' 처리(업로드→그 모드로 처리). 위키는 단일 라이터(직렬화).
282	  async function uploadMany(files: File[]) {
283	    if (busy) return;
284	    const allowExt = (n: string) => !curPol || curPol.exts.includes((n.toLowerCase().match(/\.([a-z0-9]+)$/)?.[1]) || "");
285	    const okFiles = files.filter((f) => allowExt(f.name));
286	    const blocked = files.filter((f) => !allowExt(f.name));
287	    setBusy(true); setErr(null); setResult(null);
288	    const blockedItems: UFile[] = blocked.map((f, i) => ({ id: Date.now() + 9000 + i, name: f.name, status: "error", note: curPol?.note || "지원하지 않는 형식" }));
289	    const items: UFile[] = okFiles.map((f, i) => ({ id: Date.now() + i, name: f.name, status: "pending" }));
290	    setQueue([...blockedItems, ...items]);
291	    if (okFiles.length === 0) { setBusy(false); return; }
292	    const single = okFiles.length === 1 ? (title.trim() || undefined) : undefined;
293	    const procLabel = uploadMode === "raw" ? "추가 중…" : "분석 중…";
294	    for (let i = 0; i < okFiles.length; i++) {
295	      const id = items[i].id;
296	      setQueue((q) => q.map((x) => (x.id === id ? { ...x, status: "running", note: procLabel } : x)));
297	      const r = await uploadOne(okFiles[i], single);
298	      setQueue((q) => q.map((x) => (x.id === id ? { ...x, status: r.ok ? "done" : "error", note: r.note } : x)));
299	    }
300	    setTitle("");
301	    setBusy(false);
302	    load();
303	  }
304	
305	  async function submit() {
306	    if (busy || !text.trim()) return;
307	    setBusy(true); setErr(null); setResult(null);
308	    try {
309	      const res = await fetch("/api/materials", {
310	        method: "POST", headers: { "content-type": "application/json" },
311	        body: JSON.stringify({ scope, title: title.trim() || undefined, text }),
312	      });
313	      const data = await res.json();
314	      if (!res.ok) throw new Error(data.error || "자료 추가에 실패했습니다.");
315	      if (data.status === "SKIPPED_DUP") setResult({ ok: true, note: "이미 추가된 자료입니다 (중복 건너뜀)." });
316	      else if (data.sourceId) {
317	        const r = await runProcess(data.sourceId, !!data.hasText); // 붙여넣기 텍스트는 항상 hasText
318	        setResult({ ok: r.ok, note: r.note });
319	      }
320	      setText(""); setTitle("");
321	      load();
322	    } catch (e) {
323	      setErr(e instanceof Error ? e.message : String(e));
324	    } finally {
325	      setBusy(false);
326	    }
327	  }
328	
329	  // 최근 자료 박스의 ★잔여 복구용★ — 업로드 중 이탈 등으로 PENDING/FAILED로 남은 항목을 현재 모드로 다시 처리.
330	  async function recover(s: SourceItem) {
331	    if (acting.has(s.id)) return;
332	    setActing((a) => new Set(a).add(s.id));
333	    setNotes((n) => { const c = { ...n }; delete c[s.id]; return c; });
334	    try {
335	      const r = await runProcess(s.id, !!s.hasText);
336	      setNotes((n) => ({ ...n, [r.newId]: r.note }));
337	    } catch (e) {
338	      setNotes((n) => ({ ...n, [s.id]: `오류: ${e instanceof Error ? e.message : String(e)}` }));
339	    } finally {
340	      setActing((a) => { const c = new Set(a); c.delete(s.id); return c; });
341	      await load();
342	    }
343	  }
344	
345	  return (
346	    <div className="mat-wrap">
347	      <div className="mat-col mat-col-upload">
348	        <div className="mat-card">
349	          <div className="mat-card-head"><IconUpload size={15} />자료 추가</div>
350	          <p className="mat-desc">
351	            처리 방식을 고르고 올리면 <b>바로 그 방식으로</b> 처리됩니다. 원본은 항상 그대로 보관됩니다.
352	          </p>
353	
354	          {/* 업로드 전에 처리 모드 선택 — 분석(LLM) vs 원본 그대로(토큰 0) */}
355	          <div className="mat-mode">
356	            <button type="button" className={`mat-mode-btn${uploadMode === "llm" ? " on" : ""}`} disabled={busy} onClick={() => setUploadMode("llm")}>
357	              분석해서 추가<span className="mat-mode-sub">LLM이 핵심을 정리</span>
358	            </button>
359	            <button type="button" className={`mat-mode-btn${uploadMode === "raw" ? " on" : ""}`} disabled={busy} onClick={() => setUploadMode("raw")}>
360	              원본 그대로 추가<span className="mat-mode-sub">이미 정리된 .md·텍스트 · 토큰 0</span>
361	            </button>
362	          </div>
363	
364	          {uploadMode === "llm" && models.length > 0 && (
365	            <label className="mat-model-row">
366	              <span>분석 모델</span>
367	              <ModelSelect models={models} value={model} onChange={setModel} disabled={busy} variant="mat"
368	                title="분석에 쓸 모델 (무료 한도 초과 시 백업 모델로 자동 전환됩니다)" />
369	            </label>
370	          )}
371	
372	          {uploadMode === "llm" && switchedTo && (
373	            <div className="mat-switch-note"><IconArrowsExchange size={13} />
374	              <span><b>{shortModel(model)}</b>는 문서엔 무료 한도(분당 토큰)가 작아, <b>{shortModel(switchedTo.id)}로 자동 전환</b>해 분석합니다. (짧은 질의엔 {shortModel(model)}가 빠릅니다.)</span>
375	            </div>
376	          )}
377	
378	          {uploadMode === "raw" && (
379	            <div className="mat-switch-note"><IconArrowsExchange size={13} />
380	              <span>분석 없이 원본을 그대로 위키에 추가합니다(<b>토큰 0</b>). 텍스트가 없는 PDF·이미지는 자동으로 분석됩니다.</span>
381	            </div>
382	          )}
383	
384	          {uploadMode === "llm" && (curProvider === "gemini" || curProvider === "openai-compat") && (
385	            <div className="gemini-warn"><IconAlertTriangle size={13} />
386	              <span>{curProvider === "gemini"
387	                ? <>Gemini(외부)는 빠르지만 <b>올린 자료가 Google로 전송·학습</b>됩니다. <br />민감 자료는 올리지 마세요.</>
388	                : <>이 모델(외부)은 빠르지만 <b>올린 자료가 외부 서버로 전송</b>됩니다. <br />민감 자료는 올리지 마세요.</>}</span>
389	            </div>
390	          )}
391	          <div className={`mat-drop${busy ? " busy" : ""}${dragOver ? " dragover" : ""}`}
392	            onClick={() => { if (!busy) fileRef.current?.click(); }}
393	            onDragOver={(e) => { e.preventDefault(); if (!busy) setDragOver(true); }}
394	            onDragLeave={() => setDragOver(false)}
395	            onDrop={onDrop}>
396	            <IconUpload size={20} />
397	            <span><b>{curPol?.textOnly ? "텍스트 파일(.txt·.md)을 끌어다 놓거나" : "파일을 끌어다 놓거나"}</b> 클릭해 선택 <span className="mat-multi">(여러 개 가능)</span></span>
398	            <input ref={fileRef} type="file" hidden multiple disabled={busy}
399	              accept={curPol?.accept ?? (".md,.markdown,.txt,.csv,.html,.htm,.json,.pdf,.docx,.doc,.xlsx,.xls,.pptx,.odt,.ods,.odp,.rtf,.hwp,.hwpx,.png,.jpg,.jpeg,.gif,.webp" + convertExts.map((e) => `,.${e}`).join(""))}
400	              onChange={onPickFile} />
401	          </div>
402	          <div className={`mat-formats${curPol?.textOnly ? " mat-formats-note" : ""}`}>
403	            {curPol?.note ?? "지원 형식: 텍스트(.md .txt) · PDF · 이미지 · 한글 · Word · Excel · PowerPoint · 오픈오피스 · RTF · HTML"}
404	          </div>
405	
406	          {queue.length > 0 && (
407	            <div className="mat-queue">
408	              <div className="mat-queue-head">업로드 {queue.filter((u) => u.status === "done").length}/{queue.length}</div>
409	              {queue.map((u) => (
410	                <div key={u.id} className={`mat-queue-item ${u.status}`}>
411	                  <span className="mq-dot" />
412	                  <span className="mq-name" title={u.name}>{u.name}</span>
413	                  <span className="mq-status">
414	                    {u.status === "pending" ? "대기" : u.status === "running" ? (u.note || "처리 중…") : u.status === "done" ? (u.note || "완료") : `실패: ${u.note || ""}`}
415	                  </span>
416	                </div>
417	              ))}
418	            </div>
419	          )}
420	
421	          <div className="mat-or">또는 직접 입력</div>
422	          <input className="mat-input" placeholder="제목 (단건 업로드/직접 입력 시, 비우면 자동)" value={title} maxLength={80} onChange={(e) => setTitle(e.target.value)} />
423	          <textarea className="mat-input mat-textarea" placeholder="여기에 내용을 붙여넣으세요…" value={text} onChange={(e) => setText(e.target.value)} />
424	
425	          {busy && queue.length === 0 && <div className="mat-banner muted"><IconClockHour4 size={14} />{uploadMode === "raw" ? "추가 중…" : "분석 중… (수십 초 걸릴 수 있어요)"}</div>}
426	          {err && <div className="mat-banner err"><IconAlertTriangle size={14} />{err}</div>}
427	          {result && (
428	            <div className={`mat-banner ${result.ok ? "ok" : "err"}`}>
429	              {result.ok ? <IconCircleCheck size={14} /> : <IconAlertTriangle size={14} />}<span>{result.note}</span>
430	            </div>
431	          )}
432	
433	          <button className="mat-submit" onClick={submit} disabled={busy || !text.trim()}>
434	            {busy ? <><IconClockHour4 size={14} />{uploadMode === "raw" ? "추가 중…" : "분석 중…"}</> : (uploadMode === "raw" ? "원본 그대로 추가" : "분석해서 추가")}
435	          </button>
436	        </div>
437	      </div>
438	
439	      <div className="mat-col mat-col-list">
440	        <div className="mat-card">
441	          <div className="mat-card-head"><IconFileText size={15} />최근 자료 {sources.length > 0 && `(${sources.length})`}</div>
442	          {delNote && <div className="mat-banner muted" style={{ marginBottom: 10 }}>{delNote}</div>}
443	          {sources.length === 0 ? (
444	            <p className="mat-desc">아직 올린 자료가 없습니다.</p>
445	          ) : (
446	            <div className="mat-tree">
447	              {groupByMonth(sources).map(([ym, items]) => (
448	                <SourceGroup key={ym} ym={ym} items={items} onArchive={archiveSource} onWiki={openWiki}
449	                  onRecover={recover} deleting={deleting} acting={acting} notes={notes} canManage={canManage} />
450	              ))}
451	            </div>
452	          )}
453	
454	          {/* 아카이브(소프트 삭제) 섹션 — 룸 관리자만. 펼칠 때 조회. */}
455	          {canManage && (
456	            <div className="mat-archive">
457	              <button className="mat-archive-head" onClick={() => { const n = !showArchived; setShowArchived(n); if (n) loadArchived(); }}>
458	                <IconChevronRight size={13} className={`tree-caret${showArchived ? " open" : ""}`} />
459	                <IconArchive size={14} />아카이브{archivedSources.length > 0 ? ` (${archivedSources.length})` : ""}
460	              </button>
461	              {showArchived && (
462	                archivedSources.length === 0 ? (
463	                  <p className="mat-desc mat-archive-empty">아카이브된 자료가 없습니다.</p>
464	                ) : (
465	                  <div className="mat-tree">
466	                    {groupByMonth(archivedSources).map(([ym, items]) => (
467	                      <SourceGroup key={ym} ym={ym} items={items} archivedMode canManage={canManage}
468	                        onArchive={archiveSource} onWiki={openWiki} onRecover={recover}
469	                        onRestore={restoreSource} onPurge={purgeSource}
470	                        deleting={deleting} acting={acting} notes={notes} />
471	                    ))}
472	                  </div>
473	                )
474	              )}
475	            </div>
476	          )}
477	        </div>
478	      </div>
479	    </div>
480	  );
481	}
