"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import {
  IconUpload, IconFileText, IconCircleCheck, IconAlertTriangle, IconClockHour4,
  IconChevronRight, IconTrash, IconCalendar, IconExternalLink, IconArrowUpRight, IconArticle,
  IconArrowsExchange, IconArchive, IconArrowBackUp, IconTrashX,
} from "@tabler/icons-react";
import { typeIcon } from "./fileIcons";
import ModelSelect from "./ModelSelect";

function SourceGroup({ ym, items, onArchive, onWiki, onRecover, onRestore, onPurge, deleting, acting, notes, canManage, archivedMode }: {
  ym: string; items: SourceItem[]; onArchive: (s: SourceItem) => void; onWiki: (s: SourceItem) => void;
  onRecover: (s: SourceItem) => void; onRestore?: (s: SourceItem) => void; onPurge?: (s: SourceItem) => void;
  deleting: number | null; acting: Set<number>; notes: Record<number, string>; canManage: boolean; archivedMode?: boolean;
}) {
  const [open, setOpen] = useState(true);
  return (
    <div>
      <button className="mat-group" onClick={() => setOpen((o) => !o)}>
        <IconChevronRight size={13} className={`tree-caret${open ? " open" : ""}`} />
        <IconCalendar size={14} />{ym}<span className="mat-group-count">({items.length})</span>
      </button>
      {open && items.map((s) => {
        const FIcon = typeIcon(s.type);
        // 정상 흐름은 업로드 박스에서 처리됨. 여기 PENDING/FAILED는 업로드 중 이탈 등으로 남은 '잔여' → 재처리 복구만.
        const stuck = s.status === "PENDING" || s.status === "FAILED";
        const busy = acting.has(s.id);
        const note = notes[s.id];
        return (
          <div key={s.id} className="mat-item tree">
            <FIcon size={17} className="mat-ficon" />
            <div className="mat-item-main">
              <div className="mat-item-title" title={s.title}>{s.title}</div>
              <div className="mat-item-sub"><span className="mat-ext">{s.type}</span> · {s.createdAt.slice(0, 10)}</div>
              {note && <div className="mat-item-note">{note}</div>}
            </div>
            {!archivedMode && (
              <span className={`mat-status ${s.status === "APPLIED" ? "ok" : s.status === "FAILED" ? "err" : s.status === "UNANALYZED" ? "warn" : s.status === "PENDING" ? "pend" : "muted"}`}>
                {busy ? "처리 중…" : s.status === "APPLIED" ? "반영됨" : s.status === "FAILED" ? "실패" : s.status === "SKIPPED_DUP" ? "중복" : s.status === "UNANALYZED" ? "미분석" : s.status === "PENDING" ? "분석 대기" : s.status ?? "-"}
              </span>
            )}
            <div className="mat-acts">
              <a className="mat-act" href={`/api/materials/${s.id}/raw`} target="_blank" rel="noreferrer" title="원본 열기"><IconExternalLink size={13} /></a>
              {archivedMode ? (
                <>
                  <button className="mat-act" disabled={busy} onClick={() => onRestore!(s)} title="복원"><IconArrowBackUp size={14} /></button>
                  <button className="mat-del" disabled={deleting === s.id || busy} onClick={() => onPurge!(s)} title="영구삭제"><IconTrashX size={14} /></button>
                </>
              ) : (
                <>
                  {stuck && !busy && <button className="mat-run" onClick={() => onRecover(s)} title="이 자료를 (위쪽에서 고른 방식으로) 다시 처리">재처리</button>}
                  {!stuck && <button className="mat-act" onClick={() => onWiki(s)} title="위키 페이지로 이동"><IconArrowUpRight size={13} /></button>}
                  {s.hasExtracted && (
                    <a className="mat-act" href={`/api/materials/${s.id}/extracted`} target="_blank" rel="noreferrer" title="추출본(읽은 텍스트)"><IconArticle size={13} /></a>
                  )}
                  {canManage && <button className="mat-del" disabled={deleting === s.id || busy} onClick={() => onArchive(s)} title="아카이브(삭제)"><IconTrash size={13} /></button>}
                </>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

interface SourceItem { id: number; title: string; type: string; createdAt: string; status: string | null; confidence: number | null; gate: string | null; extractStatus?: string | null; extractor?: string | null; hasExtracted?: boolean; hasText?: boolean; looksOrganized?: boolean; archived?: boolean }
interface UFile { id: number; name: string; status: "pending" | "running" | "done" | "error"; note?: string }
interface UploadPolicy { provider: string; tier?: string; textOnly: boolean; vision?: boolean; exts: string[]; accept: string; note: string }
// 모델 id를 짧고 읽기 쉽게(공급자 접두·버전 접미 제거).
function shortModel(id?: string): string {
  if (!id) return "";
  return (id.split("/").pop() || id).replace(/-17b-16e-instruct|-versatile|-instruct/g, "");
}
interface ModelOpt { id: string; label: string; provider: string; enabled: boolean; note?: string; kind?: "primary" | "backup"; backupOf?: string }

// 문서 업로드는 큰 컨텍스트가 필요 — Groq 소형-TPM 모델(gpt-oss-120b 등 8K/분)은 문서 한 개도 못 담아 폴백한다.
// llama-3.3(12K)·Gemini·Claude·로컬(ollama)은 'doc-ok'. lib/query.ts ctxBudgetFor와 같은 기준(llama-3.3만 큰 쪽).
function isSmallCtxModel(m?: ModelOpt): boolean {
  return !!m && m.provider === "openai-compat" && !/llama-3\.3-70b/i.test(m.id);
}
// 선택 모델이 소형-TPM이면, 그 모델의 백업(폴백 순서) 중 첫 'doc-ok·활성'으로 자동 전환. 없으면 그대로(백엔드 폴백이 처리).
function docModelFor(selectedId: string, models: ModelOpt[]): string {
  const sel = models.find((m) => m.id === selectedId);
  if (!sel || !isSmallCtxModel(sel)) return selectedId;
  const alt = models.find((m) => m.backupOf === selectedId && m.enabled && !isSmallCtxModel(m));
  return alt?.id ?? selectedId;
}

// 업로드 원본을 연-월(YYYY-MM)로 묶어 최신순 트리로.
function groupByMonth(sources: SourceItem[]): [string, SourceItem[]][] {
  const m = new Map<string, SourceItem[]>();
  for (const s of sources) {
    const k = s.createdAt.slice(0, 7);
    const arr = m.get(k);
    if (arr) arr.push(s); else m.set(k, [s]);
  }
  return [...m.entries()].sort((a, b) => b[0].localeCompare(a[0]));
}

export default function MaterialsTab({ scope, onOpenWiki, modelsRev }: { scope: string; onOpenWiki: (path: string) => void; modelsRev?: number }) {
  const [title, setTitle] = useState("");
  const [text, setText] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [result, setResult] = useState<{ ok: boolean; note: string } | null>(null);
  const [uploadMode, setUploadMode] = useState<"llm" | "raw">("llm"); // 업로드 박스에서 미리 고르는 처리 모드
  const [sources, setSources] = useState<SourceItem[]>([]);
  const [deleting, setDeleting] = useState<number | null>(null);
  const [delNote, setDelNote] = useState<string | null>(null);
  const [canManage, setCanManage] = useState(false); // 아카이브·영구삭제 권한(룸 관리자)
  const [archivedSources, setArchivedSources] = useState<SourceItem[]>([]);
  const [showArchived, setShowArchived] = useState(false);
  const [convertExts, setConvertExts] = useState<string[]>([]);
  const [policy, setPolicy] = useState<UploadPolicy | null>(null);
  const [models, setModels] = useState<ModelOpt[]>([]);
  const [model, setModel] = useState<string>("");
  const [policies, setPolicies] = useState<Record<string, UploadPolicy>>({});
  const [queue, setQueue] = useState<UFile[]>([]);
  const [dragOver, setDragOver] = useState(false);
  const [acting, setActing] = useState<Set<number>>(new Set()); // 분석/원본그대로 처리 중인 소스 id
  const [notes, setNotes] = useState<Record<number, string>>({}); // 처리 결과 메모(자동전환·반영 등)
  const fileRef = useRef<HTMLInputElement>(null);

  const load = useCallback(async () => {
    try {
      const res = await fetch(`/api/materials?scope=${encodeURIComponent(scope)}`, { cache: "no-store" });
      const d = await res.json();
      if (res.ok) {
        setSources(d.sources); setConvertExts(d.convertExts || []); setPolicy(d.policy || null);
        setCanManage(Boolean(d.canManage));
        setModels(d.models || []); setPolicies(d.policies || {});
        setModel((cur) => {
          const ms: ModelOpt[] = d.models || [];
          if (cur && ms.some((m) => m.id === cur && m.enabled)) return cur; // 현재 선택이 여전히 유효하면 유지
          const def = d.defaultModel && ms.some((m) => m.id === d.defaultModel && m.enabled) ? d.defaultModel : null;
          return def || ms.find((m) => m.enabled)?.id || "";
        });
      }
    } catch { /* noop */ }
  }, [scope]);

  // 아카이브된 자료 목록(복원/영구삭제 뷰) — 별도 조회(?archived=1).
  const loadArchived = useCallback(async () => {
    try {
      const res = await fetch(`/api/materials?scope=${encodeURIComponent(scope)}&archived=1`, { cache: "no-store" });
      const d = await res.json();
      if (res.ok) setArchivedSources(d.sources || []);
    } catch { /* noop */ }
  }, [scope]);

  // 선택한 인제스트 모델의 공급자에 맞는 업로드 정책(없으면 서버 기본 policy).
  const curProvider = models.find((m) => m.id === model)?.provider;
  // ★모델 id별★ 정책 — 같은 Groq라도 모델(비전 유무)에 따라 허용 확장자·안내가 달라진다.
  const curPol = policies[model] || policy;
  // ★문서 자동 전환★: 소형-TPM 모델(gpt-oss-120b 등)을 고르면 업로드는 doc-ok 모델로 보낸다
  //   (불필요한 413 왕복 제거 + 어느 모델이 처리하는지 예측 가능). switchedTo 있으면 셀렉터에 안내.
  const uploadModel = docModelFor(model, models);
  const switchedTo = uploadModel !== model ? models.find((m) => m.id === uploadModel) : null;

  useEffect(() => { setSources([]); setResult(null); setErr(null); setDelNote(null); setArchivedSources([]); setShowArchived(false); load(); }, [scope, load]);
  // 관리자가 설정에서 모델 토글 후 모달을 닫으면(modelsRev 변경) 모델·정책을 다시 불러온다.
  useEffect(() => { if (modelsRev !== undefined) load(); }, [modelsRev, load]);

  async function openWiki(s: SourceItem) {
    try {
      const res = await fetch(`/api/materials/${s.id}/pages`);
      const d = await res.json();
      if (res.ok && d.paths?.length) onOpenWiki(d.paths[0]);
      else setDelNote(`「${s.title}」에서 생성된 위키 페이지를 찾지 못했습니다.`);
    } catch {
      setDelNote("위키 페이지를 찾지 못했습니다.");
    }
  }

  // 자료 아카이브(소프트 삭제) — 목록에서 숨기고 아카이브로. 원본·위키 페이지는 보존. 룸 관리자만.
  async function archiveSource(s: SourceItem) {
    if (!confirm(`원본 「${s.title}」을(를) 아카이브할까요?\n목록에서 숨겨지며, 아카이브에서 복원하거나 영구삭제할 수 있습니다. (위키 페이지는 그대로 유지됩니다)`)) return;
    setDeleting(s.id); setDelNote(null);
    try {
      const res = await fetch(`/api/materials/${s.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "archive" }) });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error || "아카이브에 실패했습니다.");
      setDelNote(`「${s.title}」 아카이브됨`);
      await Promise.all([load(), loadArchived()]);
    } catch (e) {
      setDelNote(`오류: ${e instanceof Error ? e.message : String(e)}`);
    } finally {
      setDeleting(null);
    }
  }

  // 아카이브에서 복원 — 다시 활성 목록으로.
  async function restoreSource(s: SourceItem) {
    setDeleting(s.id); setDelNote(null);
    try {
      const res = await fetch(`/api/materials/${s.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "restore" }) });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error || "복원에 실패했습니다.");
      setDelNote(`「${s.title}」 복원됨`);
      await Promise.all([load(), loadArchived()]);
    } catch (e) {
      setDelNote(`오류: ${e instanceof Error ? e.message : String(e)}`);
    } finally {
      setDeleting(null);
    }
  }

  // 영구삭제 — 원본·사이드카 제거 + 인용 위키 페이지에 '출처 소실' 표시. 되돌릴 수 없음.
  async function purgeSource(s: SourceItem) {
    if (!confirm(`원본 「${s.title}」을(를) 영구삭제할까요? 되돌릴 수 없습니다.\n매핑된 위키 페이지는 보존되며 '출처 소실' 표시가 남습니다.`)) return;
    setDeleting(s.id); setDelNote(null);
    try {
      const res = await fetch(`/api/materials/${s.id}`, { method: "DELETE" });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error || "삭제에 실패했습니다.");
      setDelNote(`「${s.title}」 영구삭제됨 · 위키 ${d.annotated}곳에 출처 소실 표시`);
      await Promise.all([load(), loadArchived()]);
    } catch (e) {
      setDelNote(`오류: ${e instanceof Error ? e.message : String(e)}`);
    } finally {
      setDeleting(null);
    }
  }

  // 파일 선택/드롭 → 모두 서버 업로드 큐로(여러 개 가능). 수동 입력은 아래 textarea를 쓴다.
  function onPickFile(e: React.ChangeEvent<HTMLInputElement>) {
    const files = e.target.files ? [...e.target.files] : [];
    e.target.value = "";
    if (files.length) void uploadMany(files);
  }

  function onDrop(e: React.DragEvent) {
    e.preventDefault();
    setDragOver(false);
    const files = e.dataTransfer?.files ? [...e.dataTransfer.files] : [];
    if (files.length) void uploadMany(files);
  }

  // 스테이징된 소스를 ★업로드 박스에서 고른 모드★로 처리(클라 체이닝). raw는 텍스트가 있을 때만,
  // 없으면(PDF·이미지 등) 자동으로 llm. 결과 메모는 처리 후 소스 id(llm은 dedup으로 바뀜)에 단다.
  async function runProcess(sourceId: number, hasText: boolean): Promise<{ ok: boolean; note: string; newId: number }> {
    const fellBack = uploadMode === "raw" && !hasText;
    const effMode = uploadMode === "raw" && hasText ? "raw" : "llm";
    const body = effMode === "raw" ? { mode: "raw" } : { mode: "llm", model: docModelFor(model, models) };
    const res = await fetch(`/api/materials/${sourceId}/analyze`, {
      method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body),
    });
    const data = await res.json();
    if (!res.ok) return { ok: false, note: `처리 실패: ${data.error || ""}`, newId: sourceId };
    const newId: number = data.sourceId ?? sourceId;
    if (effMode === "raw") return { ok: true, note: "원본 그대로 추가됨 · 토큰 0", newId };
    const served: string | undefined = data.usedModel;
    const sw = served && served !== model ? ` · ${shortModel(model)}→${shortModel(served)} 자동전환` : "";
    const prefix = fellBack ? "텍스트 없음 → 분석함 · " : "";
    const base = data.status === "NEEDS_REVIEW" ? "검토 대기" : "분석 반영됨";
    return { ok: true, note: prefix + base + sw, newId };
  }

  // 한 파일: 스테이징 → 곧바로 선택 모드로 처리(체이닝). 사용자에겐 한 단계로 보인다.
  async function uploadOne(f: File, withTitle?: string): Promise<{ ok: boolean; note: string }> {
    try {
      const fd = new FormData();
      fd.append("scope", scope);
      if (withTitle) fd.append("title", withTitle);
      if (model) fd.append("model", model); // 업로드 정책 게이팅용(허용 확장자)
      fd.append("file", f);
      const res = await fetch("/api/materials", { method: "POST", body: fd });
      const data = await res.json();
      if (!res.ok) return { ok: false, note: data.error || "업로드 실패" };
      if (data.status === "SKIPPED_DUP") return { ok: true, note: "중복(건너뜀)" };
      if (data.unanalyzed || !data.sourceId) return { ok: true, note: "원본 보존(미분석)" };
      const r = await runProcess(data.sourceId, !!data.hasText);
      return { ok: r.ok, note: r.note };
    } catch (e) {
      return { ok: false, note: e instanceof Error ? e.message : String(e) };
    }
  }

  // 여러 파일을 '순차' 처리(업로드→그 모드로 처리). 위키는 단일 라이터(직렬화).
  async function uploadMany(files: File[]) {
    if (busy) return;
    const allowExt = (n: string) => !curPol || curPol.exts.includes((n.toLowerCase().match(/\.([a-z0-9]+)$/)?.[1]) || "");
    const okFiles = files.filter((f) => allowExt(f.name));
    const blocked = files.filter((f) => !allowExt(f.name));
    setBusy(true); setErr(null); setResult(null);
    const blockedItems: UFile[] = blocked.map((f, i) => ({ id: Date.now() + 9000 + i, name: f.name, status: "error", note: curPol?.note || "지원하지 않는 형식" }));
    const items: UFile[] = okFiles.map((f, i) => ({ id: Date.now() + i, name: f.name, status: "pending" }));
    setQueue([...blockedItems, ...items]);
    if (okFiles.length === 0) { setBusy(false); return; }
    const single = okFiles.length === 1 ? (title.trim() || undefined) : undefined;
    const procLabel = uploadMode === "raw" ? "추가 중…" : "분석 중…";
    for (let i = 0; i < okFiles.length; i++) {
      const id = items[i].id;
      setQueue((q) => q.map((x) => (x.id === id ? { ...x, status: "running", note: procLabel } : x)));
      const r = await uploadOne(okFiles[i], single);
      setQueue((q) => q.map((x) => (x.id === id ? { ...x, status: r.ok ? "done" : "error", note: r.note } : x)));
    }
    setTitle("");
    setBusy(false);
    load();
  }

  async function submit() {
    if (busy || !text.trim()) return;
    setBusy(true); setErr(null); setResult(null);
    try {
      const res = await fetch("/api/materials", {
        method: "POST", headers: { "content-type": "application/json" },
        body: JSON.stringify({ scope, title: title.trim() || undefined, text }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "자료 추가에 실패했습니다.");
      if (data.status === "SKIPPED_DUP") setResult({ ok: true, note: "이미 추가된 자료입니다 (중복 건너뜀)." });
      else if (data.sourceId) {
        const r = await runProcess(data.sourceId, !!data.hasText); // 붙여넣기 텍스트는 항상 hasText
        setResult({ ok: r.ok, note: r.note });
      }
      setText(""); setTitle("");
      load();
    } catch (e) {
      setErr(e instanceof Error ? e.message : String(e));
    } finally {
      setBusy(false);
    }
  }

  // 최근 자료 박스의 ★잔여 복구용★ — 업로드 중 이탈 등으로 PENDING/FAILED로 남은 항목을 현재 모드로 다시 처리.
  async function recover(s: SourceItem) {
    if (acting.has(s.id)) return;
    setActing((a) => new Set(a).add(s.id));
    setNotes((n) => { const c = { ...n }; delete c[s.id]; return c; });
    try {
      const r = await runProcess(s.id, !!s.hasText);
      setNotes((n) => ({ ...n, [r.newId]: r.note }));
    } catch (e) {
      setNotes((n) => ({ ...n, [s.id]: `오류: ${e instanceof Error ? e.message : String(e)}` }));
    } finally {
      setActing((a) => { const c = new Set(a); c.delete(s.id); return c; });
      await load();
    }
  }

  return (
    <div className="mat-wrap">
      <div className="mat-col mat-col-upload">
        <div className="mat-card">
          <div className="mat-card-head"><IconUpload size={15} />자료 추가</div>
          <p className="mat-desc">
            처리 방식을 고르고 올리면 <b>바로 그 방식으로</b> 처리됩니다. 원본은 항상 그대로 보관됩니다.
          </p>

          {/* 업로드 전에 처리 모드 선택 — 분석(LLM) vs 원본 그대로(토큰 0) */}
          <div className="mat-mode">
            <button type="button" className={`mat-mode-btn${uploadMode === "llm" ? " on" : ""}`} disabled={busy} onClick={() => setUploadMode("llm")}>
              분석해서 추가<span className="mat-mode-sub">LLM이 핵심을 정리</span>
            </button>
            <button type="button" className={`mat-mode-btn${uploadMode === "raw" ? " on" : ""}`} disabled={busy} onClick={() => setUploadMode("raw")}>
              원본 그대로 추가<span className="mat-mode-sub">이미 정리된 .md·텍스트 · 토큰 0</span>
            </button>
          </div>

          {uploadMode === "llm" && models.length > 0 && (
            <label className="mat-model-row">
              <span>분석 모델</span>
              <ModelSelect models={models} value={model} onChange={setModel} disabled={busy} variant="mat"
                title="분석에 쓸 모델 (무료 한도 초과 시 백업 모델로 자동 전환됩니다)" />
            </label>
          )}

          {uploadMode === "llm" && switchedTo && (
            <div className="mat-switch-note"><IconArrowsExchange size={13} />
              <span><b>{shortModel(model)}</b>는 문서엔 무료 한도(분당 토큰)가 작아, <b>{shortModel(switchedTo.id)}로 자동 전환</b>해 분석합니다. (짧은 질의엔 {shortModel(model)}가 빠릅니다.)</span>
            </div>
          )}

          {uploadMode === "raw" && (
            <div className="mat-switch-note"><IconArrowsExchange size={13} />
              <span>분석 없이 원본을 그대로 위키에 추가합니다(<b>토큰 0</b>). 텍스트가 없는 PDF·이미지는 자동으로 분석됩니다.</span>
            </div>
          )}

          {uploadMode === "llm" && (curProvider === "gemini" || curProvider === "openai-compat") && (
            <div className="gemini-warn"><IconAlertTriangle size={13} />
              <span>{curProvider === "gemini"
                ? <>Gemini(외부)는 빠르지만 <b>올린 자료가 Google로 전송·학습</b>됩니다. <br />민감 자료는 올리지 마세요.</>
                : <>이 모델(외부)은 빠르지만 <b>올린 자료가 외부 서버로 전송</b>됩니다. <br />민감 자료는 올리지 마세요.</>}</span>
            </div>
          )}
          <div className={`mat-drop${busy ? " busy" : ""}${dragOver ? " dragover" : ""}`}
            onClick={() => { if (!busy) fileRef.current?.click(); }}
            onDragOver={(e) => { e.preventDefault(); if (!busy) setDragOver(true); }}
            onDragLeave={() => setDragOver(false)}
            onDrop={onDrop}>
            <IconUpload size={20} />
            <span><b>{curPol?.textOnly ? "텍스트 파일(.txt·.md)을 끌어다 놓거나" : "파일을 끌어다 놓거나"}</b> 클릭해 선택 <span className="mat-multi">(여러 개 가능)</span></span>
            <input ref={fileRef} type="file" hidden multiple disabled={busy}
              accept={curPol?.accept ?? (".md,.markdown,.txt,.csv,.html,.htm,.json,.pdf,.docx,.doc,.xlsx,.xls,.pptx,.odt,.ods,.odp,.rtf,.hwp,.hwpx,.png,.jpg,.jpeg,.gif,.webp" + convertExts.map((e) => `,.${e}`).join(""))}
              onChange={onPickFile} />
          </div>
          <div className={`mat-formats${curPol?.textOnly ? " mat-formats-note" : ""}`}>
            {curPol?.note ?? "지원 형식: 텍스트(.md .txt) · PDF · 이미지 · 한글 · Word · Excel · PowerPoint · 오픈오피스 · RTF · HTML"}
          </div>

          {queue.length > 0 && (
            <div className="mat-queue">
              <div className="mat-queue-head">업로드 {queue.filter((u) => u.status === "done").length}/{queue.length}</div>
              {queue.map((u) => (
                <div key={u.id} className={`mat-queue-item ${u.status}`}>
                  <span className="mq-dot" />
                  <span className="mq-name" title={u.name}>{u.name}</span>
                  <span className="mq-status">
                    {u.status === "pending" ? "대기" : u.status === "running" ? (u.note || "처리 중…") : u.status === "done" ? (u.note || "완료") : `실패: ${u.note || ""}`}
                  </span>
                </div>
              ))}
            </div>
          )}

          <div className="mat-or">또는 직접 입력</div>
          <input className="mat-input" placeholder="제목 (단건 업로드/직접 입력 시, 비우면 자동)" value={title} maxLength={80} onChange={(e) => setTitle(e.target.value)} />
          <textarea className="mat-input mat-textarea" placeholder="여기에 내용을 붙여넣으세요…" value={text} onChange={(e) => setText(e.target.value)} />

          {busy && queue.length === 0 && <div className="mat-banner muted"><IconClockHour4 size={14} />{uploadMode === "raw" ? "추가 중…" : "분석 중… (수십 초 걸릴 수 있어요)"}</div>}
          {err && <div className="mat-banner err"><IconAlertTriangle size={14} />{err}</div>}
          {result && (
            <div className={`mat-banner ${result.ok ? "ok" : "err"}`}>
              {result.ok ? <IconCircleCheck size={14} /> : <IconAlertTriangle size={14} />}<span>{result.note}</span>
            </div>
          )}

          <button className="mat-submit" onClick={submit} disabled={busy || !text.trim()}>
            {busy ? <><IconClockHour4 size={14} />{uploadMode === "raw" ? "추가 중…" : "분석 중…"}</> : (uploadMode === "raw" ? "원본 그대로 추가" : "분석해서 추가")}
          </button>
        </div>
      </div>

      <div className="mat-col mat-col-list">
        <div className="mat-card">
          <div className="mat-card-head"><IconFileText size={15} />최근 자료 {sources.length > 0 && `(${sources.length})`}</div>
          {delNote && <div className="mat-banner muted" style={{ marginBottom: 10 }}>{delNote}</div>}
          {sources.length === 0 ? (
            <p className="mat-desc">아직 올린 자료가 없습니다.</p>
          ) : (
            <div className="mat-tree">
              {groupByMonth(sources).map(([ym, items]) => (
                <SourceGroup key={ym} ym={ym} items={items} onArchive={archiveSource} onWiki={openWiki}
                  onRecover={recover} deleting={deleting} acting={acting} notes={notes} canManage={canManage} />
              ))}
            </div>
          )}

          {/* 아카이브(소프트 삭제) 섹션 — 룸 관리자만. 펼칠 때 조회. */}
          {canManage && (
            <div className="mat-archive">
              <button className="mat-archive-head" onClick={() => { const n = !showArchived; setShowArchived(n); if (n) loadArchived(); }}>
                <IconChevronRight size={13} className={`tree-caret${showArchived ? " open" : ""}`} />
                <IconArchive size={14} />아카이브{archivedSources.length > 0 ? ` (${archivedSources.length})` : ""}
              </button>
              {showArchived && (
                archivedSources.length === 0 ? (
                  <p className="mat-desc mat-archive-empty">아카이브된 자료가 없습니다.</p>
                ) : (
                  <div className="mat-tree">
                    {groupByMonth(archivedSources).map(([ym, items]) => (
                      <SourceGroup key={ym} ym={ym} items={items} archivedMode canManage={canManage}
                        onArchive={archiveSource} onWiki={openWiki} onRecover={recover}
                        onRestore={restoreSource} onPurge={purgeSource}
                        deleting={deleting} acting={acting} notes={notes} />
                    ))}
                  </div>
                )
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

