1	import { NextResponse } from "next/server";
2	import { getSessionUser } from "@/lib/auth/session";
3	import { allowedScopes, scopeWikiPrefix } from "@/lib/acl/scope";
4	import { prisma } from "@/lib/db";
5	import { analyzeSource, fileSourceAsIs } from "@/lib/ingest";
6	import { resolveIngestModel } from "@/lib/models";
7	import { checkDailyBudget } from "@/lib/cost";
8	
9	// 스테이징된 자료를 ★실행★ — mode:"llm"=LLM 분석(토큰), mode:"raw"=원본 그대로 파일링(토큰 0).
10	export const runtime = "nodejs";
11	export const maxDuration = 300;
12	
13	export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
14	  const user = await getSessionUser();
15	  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
16	  const id = Number((await params).id);
17	  if (!Number.isInteger(id) || id <= 0) return NextResponse.json({ error: "잘못된 id입니다." }, { status: 400 });
18	
19	  const source = await prisma.source.findUnique({ where: { id } });
20	  if (!source) return NextResponse.json({ error: "자료를 찾을 수 없습니다." }, { status: 404 });
21	  // ACL: 접근 가능한 scope의 자료만(인제스트 적용 강제지점).
22	  const allowed = new Set((await allowedScopes(user)).map((s) => scopeWikiPrefix(s.id)));
23	  if (!allowed.has(source.teamScope)) return NextResponse.json({ error: "접근 권한이 없습니다." }, { status: 403 });
24	
25	  const { mode, model } = await req.json().catch(() => ({}));
26	  try {
27	    if (mode === "raw") {
28	      // 토큰 0 — 이미 정리된 텍스트를 위키 페이지로 직접 파일링.
29	      return NextResponse.json(await fileSourceAsIs(id));
30	    }
31	    // mode "llm"(기본): 비용 상한 체크 후 실제 LLM 인제스트.
