import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth/session";
import { allowedScopes, scopeWikiPrefix } from "@/lib/acl/scope";
import { prisma } from "@/lib/db";
import { analyzeSource, fileSourceAsIs } from "@/lib/ingest";
import { resolveIngestModel } from "@/lib/models";
import { checkDailyBudget } from "@/lib/cost";

// 스테이징된 자료를 ★실행★ — mode:"llm"=LLM 분석(토큰), mode:"raw"=원본 그대로 파일링(토큰 0).
export const runtime = "nodejs";
export const maxDuration = 300;

export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const id = Number((await params).id);
  if (!Number.isInteger(id) || id <= 0) return NextResponse.json({ error: "잘못된 id입니다." }, { status: 400 });

  const source = await prisma.source.findUnique({ where: { id } });
  if (!source) return NextResponse.json({ error: "자료를 찾을 수 없습니다." }, { status: 404 });
  // ACL: 접근 가능한 scope의 자료만(인제스트 적용 강제지점).
  const allowed = new Set((await allowedScopes(user)).map((s) => scopeWikiPrefix(s.id)));
  if (!allowed.has(source.teamScope)) return NextResponse.json({ error: "접근 권한이 없습니다." }, { status: 403 });

  const { mode, model } = await req.json().catch(() => ({}));
  try {
    if (mode === "raw") {
      // 토큰 0 — 이미 정리된 텍스트를 위키 페이지로 직접 파일링.
      return NextResponse.json(await fileSourceAsIs(id));
    }
    // mode "llm"(기본): 비용 상한 체크 후 실제 LLM 인제스트.
    const budget = await checkDailyBudget(user.id);
    if (budget.exceeded) {
      return NextResponse.json({ error: `오늘 토큰 사용 한도(${budget.limit.toLocaleString()})를 초과했습니다.` }, { status: 429 });
    }
    const picked = await resolveIngestModel(typeof model === "string" ? model : undefined);
    return NextResponse.json(await analyzeSource(id, { model: picked.model, provider: picked.provider, think: picked.think }));
  } catch (err) {
    return NextResponse.json({ error: String(err) }, { status: 500 });
  }
}

