export async function analyzeSource(sourceId: number, opts: { model?: string; provider?: string; think?: boolean }): Promise<IngestResult> {
  const source = await prisma.source.findUnique({ where: { id: sourceId } });
  if (!source) throw new Error("자료를 찾을 수 없습니다.");
  const scope = source.teamScope;
  const rawBytes = await fs.readFile(wikiAbsPath(source.rawPath));
  const rawExt = (source.rawPath.split(".").pop() || "md").toLowerCase();
  const base = {
    scope, title: source.title, userId: source.uploadedBy, rawBytes, rawExt,
    mimeType: source.mimeType ?? undefined, byteSize: source.byteSize ?? undefined, originalName: source.originalName ?? undefined,
    model: opts.model, provider: opts.provider, think: opts.think,
  };
  if (source.normalizedPath) {
    const normalized = await fs.readFile(wikiAbsPath(source.normalizedPath), "utf8");
    return ingestText({ ...base, type: source.type, text: normalized, extractor: source.extractor ?? undefined, extractStatus: source.extractStatus ?? undefined, normalizedText: normalized });
  }
  const isPdf = source.type === "PDF" || rawExt === "pdf";
  const isImg = source.type === "IMAGE" || ["png", "jpg", "jpeg", "gif", "webp"].includes(rawExt);
  if (isImg) {
    const imgMime = source.mimeType || sniffImageMime(rawBytes) || "image/png";
    return ingestText({ ...base, type: "IMAGE", extractor: "vision", extractStatus: "FULL",
      text: `이미지 파일명: ${source.originalName ?? source.title}. 이 이미지를 분석해 핵심 정보를 위키 지식으로 정리하세요.`,
      images: [{ mediaType: imgMime, dataBase64: rawBytes.toString("base64") }] });
  }
  if (isPdf) {
    return ingestText({ ...base, type: "PDF", rawExt: "pdf", extractor: "pdf-vision", extractStatus: "FULL",
      text: `PDF 파일명: ${source.originalName ?? source.title}. 이 문서를 분석해 정리하세요.`,
      documents: [{ mediaType: "application/pdf", dataBase64: rawBytes.toString("base64") }] });
  }
  throw new Error("분석할 텍스트가 없습니다(비전 모델이 필요한 형식). Gemini/Claude 모델로 다시 시도하세요.");
}

/**
 * [원본 그대로] — ★LLM 없이(토큰 0)★ 텍스트 원본을 위키 페이지로 직접 파일링한다. 이미 정리된 문서용.
 * topics/<slug>.md로 저장(쿼리 로드 대상) + index 한 줄 추가 + APPLIED 잡 생성("반영됨"). recordUsage 없음.
 */
export async function fileSourceAsIs(sourceId: number): Promise<IngestResult> {
  const source = await prisma.source.findUnique({ where: { id: sourceId } });
  if (!source) throw new Error("자료를 찾을 수 없습니다.");
  await assertWikiReady();
  const scope = source.teamScope;
  let body = source.normalizedPath
    ? await fs.readFile(wikiAbsPath(source.normalizedPath), "utf8")
    : (await fs.readFile(wikiAbsPath(source.rawPath))).toString("utf8");
  body = body.trim();
  if (!body) throw new Error("텍스트가 없어 '원본 그대로' 추가를 할 수 없습니다. [분석]을 사용하세요.");

  const slug = slugifyTitle(source.title) || `note-${source.id}`;
  const pageRel = `${scope}/topics/${slug}.md`;
  const pageContent = hasFrontmatter(body)
    ? body + "\n"
    : frontmatterOf({
        title: source.title.replace(/\n/g, " ").slice(0, 80), type: "note", scope,
        sources: JSON.stringify([source.sha256]), updated: new Date().toISOString().slice(0, 10),
      }) + "\n" + body + "\n";

  const curIndex = await loadIndex(scope);
  const indexLine = `- [${source.title.replace(/\n/g, " ").slice(0, 60)}](topics/${slug}.md) — 원본 그대로 추가`;
  const newIndex = curIndex.includes(`topics/${slug}.md`)
    ? curIndex
    : (curIndex.trim() ? curIndex.trimEnd() + "\n" + indexLine + "\n" : `# ${scope} 목차\n\n${indexLine}\n`);

  const editSet: EditSet = {
    edits: [
      { op: "create", path: pageRel, content: pageContent },
      { op: "create", path: `${scope}/index.md`, content: newIndex },
    ],
    log_entry: `원본 그대로 추가(분석 없음): ${source.title}`,
    confidence: 1,
  };

  const { commitSha, changed } = await withWikiWriteLock(async () => {
    const changed = await applyEditSet(scope, editSet);
    const commitSha = await commitAll(`import(${scope}): ${source.title} [원본그대로]`, { sourceSha256: source.sha256, sourceType: source.type, team: scope, gate: "RAW_IMPORT" });
    return { commitSha, changed };
  });

  const job = await prisma.ingestJob.create({
    data: { sourceId: source.id, teamScope: scope, status: "APPLIED", model: "(분석없음)", gate: "RAW_IMPORT", confidence: 1, commitSha },
  });
  return { status: "APPLIED", sourceId: source.id, jobId: job.id, commitSha, changedPaths: changed, confidence: 1, usedModel: "원본 그대로(분석 안 함)" };
}

