"use client";

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import { IconFileText, IconChevronRight, IconBook2, IconExternalLink, IconArrowUp, IconX, IconArchive, IconArrowBackUp, IconTrash, IconTrashX, IconPencil, IconSparkles } from "@tabler/icons-react";
import { typeIcon, categoryIcon } from "./fileIcons";
import { renderMarkdown } from "./markdown";

interface TNode { name: string; full?: string; dirs: Map<string, TNode> }

function buildTree(files: string[], scope: string): TNode {
  const root: TNode = { name: scope, dirs: new Map() };
  for (const f of files) {
    const rel = f.startsWith(scope + "/") ? f.slice(scope.length + 1) : f;
    const segs = rel.split("/");
    let node = root;
    segs.forEach((seg, i) => {
      const isFile = i === segs.length - 1;
      if (isFile) {
        node.dirs.set(seg, { name: seg, full: f, dirs: new Map() });
      } else {
        if (!node.dirs.has(seg)) node.dirs.set(seg, { name: seg, dirs: new Map() });
        node = node.dirs.get(seg)!;
      }
    });
  }
  return root;
}

function sortedChildren(n: TNode): TNode[] {
  return [...n.dirs.values()].sort((a, b) => {
    const af = a.dirs.size > 0 && !a.full, bf = b.dirs.size > 0 && !b.full;
    if (af !== bf) return af ? -1 : 1; // 폴더 먼저
    return a.name.localeCompare(b.name);
  });
}

function TreeItem({ node, depth, selected, onSelect, types }: {
  node: TNode; depth: number; selected: string | null; onSelect: (p: string) => void; types: Record<string, string>;
}) {
  const [open, setOpen] = useState(true);
  const pad = { paddingLeft: 8 + depth * 14 };

  if (node.full) {
    const label = node.name.replace(/\.md$/, "");
    // 원본 자료 타입이 알려져 있으면 그 확장자 아이콘으로(PDF·Word…), 없으면 카테고리 아이콘.
    const srcType = types[node.full];
    const FI = srcType ? typeIcon(srcType) : categoryIcon(node.name, true);
    return (
      <button className={`tree-file${selected === node.full ? " active" : ""}`} style={pad} onClick={() => onSelect(node.full!)} title={srcType ? `원본: ${srcType}` : undefined}>
        <FI size={14} />{label}
      </button>
    );
  }
  const DI = categoryIcon(node.name, false);
  return (
    <div>
