const [editNote, setEditNote] = useState("");

const loadTree = useCallback(async () => {
  try {
    const res = await fetch(`/api/wiki?scope=${encodeURIComponent(scope)}`);
    const d = await res.json();
    if (res.ok) { setFiles(d.files); setWikiScope(d.scope); setTypes(d.types || {}); setTitles(d.titles || {}); }
  } catch { /* noop */ }
}, [scope]);

// 아카이브 목록 + 이 scope의 관리 권한(canManage) 로드.
const loadArchive = useCallback(async () => {
  try {
    const res = await fetch(`/api/wiki/archive?scope=${encodeURIComponent(scope)}`);
    const d = await res.json();
    if (res.ok) { setArchived(d.pages || []); setCanManage(Boolean(d.canManage)); }
  } catch { /* noop */ }
}, [scope]);

// scope 바뀌면 트리(파일/제목)·아카이브만 다시 로드. 탭·활성·본문 캐시는 ★룸별로 유지★(초기화 안 함).
useEffect(() => {
  setFiles([]); setTypes({}); setTitles({}); setArchived([]); setCanManage(false); setShowArchive(false);
  setEditing(null); setEditNote("");
  loadTree(); loadArchive();
}, [scope, loadTree, loadArchive]);

// 페이지 본문 로드(캐시에 없을 때만; ref로 중복요청 방지).
const loadPage = useCallback(async (p: string) => {
  if (loadedRef.current.has(p) || loadingRef.current.has(p)) return;
  loadingRef.current.add(p);
  setLoadingPaths((s) => new Set(s).add(p));
  try {
    const res = await fetch(`/api/wiki?scope=${encodeURIComponent(scope)}&path=${encodeURIComponent(p)}`);
    const d = await res.json();
    setPages((prev) => ({ ...prev, [p]: { content: res.ok ? d.content : `오류: ${d.error}`, sources: res.ok ? (d.sources || []) : [] } }));
  } catch (e) {
    setPages((prev) => ({ ...prev, [p]: { content: `오류: ${String(e)}`, sources: [] } }));
  } finally {
    loadedRef.current.add(p);
    loadingRef.current.delete(p);
    setLoadingPaths((s) => { const n = new Set(s); n.delete(p); return n; });
  }
}, [scope]);

// 페이지 열기: 탭 추가 + 활성화 + (필요 시) 본문 로드.
const openPage = useCallback((p: string) => {
  setTabs((prev) => (prev.includes(p) ? prev : [...prev, p]));
  setActive(p);
  void loadPage(p);
}, [setTabs, setActive, loadPage]);

const closeTab = useCallback((p: string) => {
  const cur = tabsByScope[scope] ?? [];
  const idx = cur.indexOf(p);
  const next = cur.filter((t) => t !== p);
  setTabs(() => next);
  if ((activeByScope[scope] ?? null) === p) setActive(next[idx] ?? next[idx - 1] ?? null); // 닫은 탭이 활성이면 인접 탭으로
  setPages((prev) => { const n = { ...prev }; delete n[p]; return n; }); // 캐시 비움(재오픈 시 재로드)
  loadedRef.current.delete(p);
}, [scope, tabsByScope, activeByScope, setTabs, setActive]);

// ★탭 바는 최대 2줄★ — 넘치면 가장 오래된(왼쪽·비활성) 탭부터 닫는다. 측정→닫기→재측정(수렴).
// useLayoutEffect라 페인트 전에 처리돼 3줄이 깜빡이지 않는다.
useLayoutEffect(() => {
