  const padTop = parseFloat(st.paddingTop) || 0;
  const padBottom = parseFloat(st.paddingBottom) || 0;
  const gap = parseFloat(st.rowGap || st.gap || "0") || 0;
  const twoRows = padTop + padBottom + first.offsetHeight * 2 + gap + 2; // 2줄 허용 높이(상하 패딩+행간+여유)
