import type { FallbackTarget } from "./anthropic";
import { geminiEnabled, geminiDefaultModel } from "./gemini";
import { openaiCompatEnabled, openaiCompatModelVision } from "./openai-compat";

// 자동 폴백 체인 — 1순위 모델이 한도(429)·일시오류면 ★같은 역할★의 백업으로 순서대로 재시도.
// (선택기에는 1순위만 노출하고, 백업 모델은 여기서만 자동으로 쓰인다.)
//   이미지·웹·텍스트(Gemini) →  llama-4-scout(비전 가능) → gpt-oss-120b(텍스트)
//   고품질 텍스트(gpt-oss-120b) →  llama-3.3-70b(한국어) → gpt-oss-20b(가벼움) → Gemini
// 백업은 해당 공급자 키가 설정된 것만 포함한다.

function visionOf(model: string, provider: string): boolean {
  if (provider === "gemini" || provider === "anthropic") return true;
  if (provider === "openai-compat") return openaiCompatModelVision(model);
  return false;
}

export function fallbackChainFor(model: string, provider: string): FallbackTarget[] {
  const groq = openaiCompatEnabled();
  const gem = geminiEnabled();
  const raw: { model: string; provider: string }[] = [];

  if (provider === "gemini") {
    // 비전·텍스트 모두 가능한 scout를 먼저(이미지 입력도 폴백되게) → 텍스트 고품질
    if (groq) raw.push({ model: "meta-llama/llama-4-scout-17b-16e-instruct", provider: "openai-compat" });
    if (groq) raw.push({ model: "openai/gpt-oss-120b", provider: "openai-compat" });
  } else if (provider === "openai-compat" && model === "openai/gpt-oss-120b") {
    if (groq) raw.push({ model: "llama-3.3-70b-versatile", provider: "openai-compat" });
    if (groq) raw.push({ model: "openai/gpt-oss-20b", provider: "openai-compat" });
    if (gem) raw.push({ model: geminiDefaultModel(), provider: "gemini" });
  }
  // ollama(로컬·민감)·anthropic은 폴백 없음(외부 전송 금지 / 단일 공급자).

  return raw.map((t) => ({ ...t, vision: visionOf(t.model, t.provider) }));
}

