1	import { NextResponse } from "next/server";
2	import { promises as fs } from "node:fs";
3	import path from "node:path";
4	import { getSessionUser } from "@/lib/auth/session";
5	import { assertScopeAllowed, canManageScope, scopeWikiPrefix } from "@/lib/acl/scope";
6	import { wikiAbsPath, assertInScope } from "@/lib/wiki/paths";
7	import { assertWikiReady, commitAll, withWikiWriteLock } from "@/lib/wiki/repo";
8	import { prisma } from "@/lib/db";
9	
10	// 위키 탭 리더 — scope 위키의 폴더 트리(파일 목록) + 단일 페이지 본문. ACL 강제지점2(페이지 로드).
11	export const runtime = "nodejs";
12	
13	async function listMd(absDir: string, relBase: string): Promise<string[]> {
14	  let entries: import("node:fs").Dirent[];
15	  try {
16	    entries = await fs.readdir(absDir, { withFileTypes: true });
17	  } catch {
18	    return [];
19	  }
20	  const out: string[] = [];
21	  for (const e of entries) {
22	    if (e.name.startsWith(".")) continue;
23	    const rel = `${relBase}/${e.name}`;
24	    if (e.isDirectory()) out.push(...(await listMd(path.join(absDir, e.name), rel)));
25	    else if (e.name.endsWith(".md")) out.push(rel);
26	  }
27	  return out;
28	}
29	
30	export async function GET(req: Request) {
31	  const user = await getSessionUser();
32	  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
33	  const url = new URL(req.url);
34	  const scope = url.searchParams.get("scope") ?? "";
35	  const pagePath = url.searchParams.get("path");
36	
37	  // ACL 강제지점2: 페이지 로드 — 허용 scope만
38	  try {
39	    await assertScopeAllowed(user, scope);
40	  } catch {
41	    return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
42	  }
43	  const wikiScope = scopeWikiPrefix(scope);
44	
45	  // 단일 페이지 본문
46	  if (pagePath) {
47	    try {
48	      assertInScope(wikiScope, pagePath);
49	    } catch {
50	      return NextResponse.json({ error: "scope 밖 경로입니다." }, { status: 400 });
51	    }
52	    if (!pagePath.endsWith(".md")) return NextResponse.json({ error: "md 파일만 열람합니다." }, { status: 400 });
53	    try {
54	      const content = await fs.readFile(wikiAbsPath(pagePath), "utf8");
55	      // 이 페이지가 인용한 원본 자료(frontmatter sources의 sha) → 위키에서 원본 열람·이미지 표시용
56	      const shas = [...content.matchAll(/sha256:([a-f0-9]{64})/g)].map((m) => m[1]);
57	      let sources: { id: number; title: string; type: string }[] = [];
58	      if (shas.length) {
59	        const rows = await prisma.source.findMany({
60	          where: { sha256: { in: shas }, teamScope: wikiScope },
61	          select: { id: true, title: true, type: true },
62	          orderBy: { id: "asc" },
63	        });
64	        sources = rows;
65	      }
66	      return NextResponse.json({ path: pagePath, content, sources });
67	    } catch {
68	      return NextResponse.json({ error: "페이지를 찾을 수 없습니다." }, { status: 404 });
69	    }
70	  }
71	
72	  // 폴더 트리(파일 경로 목록) + 각 페이지의 원본 자료 타입(첫 인용 sha) → 트리 아이콘 구분
73	  const files = (await listMd(wikiAbsPath(wikiScope), wikiScope)).sort();
74	  const fileSha: Record<string, string> = {};
75	  const titles: Record<string, string> = {}; // 경로→제목(위키 내부 [[링크]] 해석용)
76	  const shaSet = new Set<string>();
77	  await Promise.all(
78	    files.map(async (f) => {
79	      const base = f.split("/").pop();
80	      if (base === "index.md" || base === "log.md") return;
81	      try {
82	        const c = await fs.readFile(wikiAbsPath(f), "utf8");
83	        const m = c.match(/sha256:([a-f0-9]{64})/);
84	        if (m) { fileSha[f] = m[1]; shaSet.add(m[1]); }
85	        const fm = c.match(/^---\n([\s\S]*?)\n---/); // frontmatter title 추출(있으면)
86	        const tm = fm && fm[1].match(/^title:\s*(.+)$/m);
87	        if (tm) titles[f] = tm[1].trim().replace(/^["']|["']$/g, "");
88	      } catch { /* skip */ }
89	    }),
90	  );
91	  const types: Record<string, string> = {};
92	  if (shaSet.size) {
93	    const rows = await prisma.source.findMany({
94	      where: { teamScope: wikiScope, sha256: { in: [...shaSet] } },
95	      select: { sha256: true, type: true },
96	    });
97	    const shaType: Record<string, string> = {};
98	    for (const r of rows) shaType[r.sha256] = r.type;
99	    for (const [f, sha] of Object.entries(fileSha)) if (shaType[sha]) types[f] = shaType[sha];
100	  }
101	  return NextResponse.json({ scope: wikiScope, files, types, titles });
102	}
103	
104	// PUT {scope, path, content} — 위키 페이지 직접 편집(교정용). 룸 관리자만(canManageScope).
105	// 단일 라이터(withWikiWriteLock+commitAll)로 커밋 → git 이력이 곧 되돌리기(docs/13). 상호링크·index 자동정리는 안 함.
106	export async function PUT(req: Request) {
107	  const user = await getSessionUser();
108	  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
109	  const body = await req.json().catch(() => ({}));
110	  const scope = typeof body.scope === "string" ? body.scope : "";
111	  const pagePath = typeof body.path === "string" ? body.path : "";
112	  const content = body.content;
113	  if (typeof content !== "string") return NextResponse.json({ error: "content가 필요합니다." }, { status: 400 });
114	  if (!pagePath.endsWith(".md")) return NextResponse.json({ error: "md 페이지만 편집합니다." }, { status: 400 });
115	  try {
116	    await assertScopeAllowed(user, scope);
117	  } catch {
