import { ollamaBaseUrl } from "./ollama";
import { providerFor, modelFor } from "./anthropic";
import { geminiEnabled, geminiDefaultModel } from "./gemini";
import { openaiCompatEnabled, openaiCompatModels, openaiCompatLabel } from "./openai-compat";
import { fallbackChainFor } from "./fallback";
import { disabledModelIds } from "./modelSettings";

// 채팅(질의)에서 고를 수 있는 모델 목록. 로컬(ollama)은 받아진 것만, Claude는 결제 시만 활성.
// 백업 모델(자동 폴백 전용)도 '↳ 백업'으로 함께 노출해 라인업을 알 수 있게 한다.
// enabled = (공급자 사용 가능) && (관리자가 끄지 않음).

export interface ModelOption {
  id: string;
  label: string;
  provider: "ollama" | "anthropic" | "gemini" | "openai-compat";
  enabled: boolean;
  note?: string;
  kind?: "primary" | "backup"; // primary=선택 대표, backup=자동 폴백 대상
  backupOf?: string; // backup이면 어느 1순위를 대체하는지(모델 id)
  available?: boolean; // 공급자 키/조건 충족(관리자 토글과 무관)
  adminDisabled?: boolean; // 관리자가 끔
}

// 결제 시 활성화될 Claude 후보(고정).
const CLAUDE_MODELS: { id: string; label: string }[] = [
  { id: "claude-opus-4-8", label: "Claude Opus 4.8 · 최고품질·비전·웹검색" },
  { id: "claude-sonnet-4-6", label: "Claude Sonnet 4.6 · 균형·비전·웹검색" },
  { id: "claude-haiku-4-5", label: "Claude Haiku 4.5 · 빠름·비전" },
];

export function anthropicEnabled(): boolean {
  return process.env.ANTHROPIC_ENABLED === "true" && !!process.env.ANTHROPIC_API_KEY;
}

// thinking(추론) 모드를 지원하는 로컬 모델 패턴. 켜면 더 꼼꼼하지만 느림.
const THINKING_RE = /^(qwen3|deepseek-r1|qwq)/i;
export function isThinkingModel(name: string): boolean {
  return THINKING_RE.test(name);
}

export async function listQueryModels(): Promise<ModelOption[]> {
  const disabled = await disabledModelIds();
  const out: ModelOption[] = [];
  const ocAll = openaiCompatModels();
  const ocLabel = openaiCompatLabel();
  const ocOk = openaiCompatEnabled();
  const gemModel = geminiDefaultModel();
  const gemOk = geminiEnabled();
  const claudeOk = anthropicEnabled();

  // 1순위(대표) id 모음 — 백업 표시에서 다른 1순위가 중복 노출되지 않게.
  const primaryIds = new Set<string>([gemModel, ...ocAll.filter((m) => m.primary).map((m) => m.id), ...CLAUDE_MODELS.map((c) => c.id)]);

  const providerAvailable = (provider: string): boolean =>
    provider === "gemini" ? gemOk : provider === "openai-compat" ? ocOk : provider === "anthropic" ? claudeOk : true;

  function add(id: string, label: string, provider: ModelOption["provider"], available: boolean, kind: "primary" | "backup", backupOf?: string, naNote?: string) {
    const adminOff = disabled.has(id);
    out.push({
      id, label, provider, kind, backupOf, available, adminDisabled: adminOff,
      enabled: available && !adminOff,
      note: adminOff ? "관리자가 끔" : available ? undefined : naNote,
    });
  }
  // 1순위 뒤에 그 백업들(자동 폴백 대상)을 '↳ 백업'으로 이어 붙인다(다른 1순위는 제외).
  function addBackupsOf(primaryId: string, provider: string) {
    for (const fb of fallbackChainFor(primaryId, provider)) {
      if (primaryIds.has(fb.model)) continue;
      const oc = ocAll.find((m) => m.id === fb.model);
      const blabel = `↳ 백업 · ${oc ? oc.label : fb.model}${fb.provider === "openai-compat" ? ` · ${ocLabel}` : ""}`;
      add(fb.model, blabel, fb.provider as ModelOption["provider"], providerAvailable(fb.provider), "backup", primaryId, "키 필요");
    }
  }

  // 로컬(ollama): 실제 pull된 모델만. 추론 모델은 '빠름'·'추론' 두 줄.
  try {
    const res = await fetch(`${ollamaBaseUrl()}/api/tags`, { signal: AbortSignal.timeout(2000) });
    if (res.ok) {
      const j = (await res.json()) as { models?: { name: string }[] };
      for (const m of j.models ?? []) {
        if (/embed/i.test(m.name)) continue; // 임베딩 전용 모델(nomic-embed-text 등)은 질의 대상 아님 — lib/embed.ts가 직접 사용
        add(m.name, `${m.name} · 사내보관·민감자료 OK · 로컬무료`, "ollama", true, "primary");
        if (isThinkingModel(m.name)) add(`${m.name}#think`, `${m.name} · 추론(느림·꼼꼼) · 로컬무료`, "ollama", true, "primary");
      }
    }
  } catch { /* ollama 미가동 */ }

  // Gemini(1순위·이미지·웹검색) + 백업(llama-4-scout)
  add(gemModel, `${gemModel} · 이미지·웹검색 · 무료·외부`, "gemini", gemOk, "primary", undefined, "GEMINI_API_KEY 필요");
  addBackupsOf(gemModel, "gemini");

  // Groq 고품질 텍스트(1순위 gpt-oss-120b) + 백업(llama-3.3, gpt-oss-20b)
  const oss = ocAll.find((m) => m.primary);
  if (oss) {
    add(oss.id, `${oss.label} · 무료·${ocLabel}`, "openai-compat", ocOk, "primary", undefined, "OPENAI_COMPAT_API_KEY 필요");
    addBackupsOf(oss.id, "openai-compat");
  }

  // Claude(결제 시)
  for (const c of CLAUDE_MODELS) add(c.id, c.label, "anthropic", claudeOk, "primary", undefined, "API 결제 필요");

  return out;
}

/**
 * 요청 모델 id를 검증(허용+활성)해 {model, provider, think}로. 무효면 해당 용도 환경 기본값으로 폴백.
 * id가 `<model>#think`면 think=true(Ollama엔 base 모델명만 보냄).
 */
export async function resolveModel(requestedId: string | undefined, purpose: "ingest" | "query"): Promise<{ model: string; provider: string; think: boolean }> {
  if (requestedId) {
    const found = (await listQueryModels()).find((o) => o.id === requestedId && o.enabled);
    if (found) {
      const think = requestedId.endsWith("#think");
      return { model: think ? requestedId.slice(0, -"#think".length) : requestedId, provider: found.provider, think };
    }
  }
  return { model: modelFor(purpose), provider: providerFor(purpose), think: false };
}
export const resolveQueryModel = (id?: string) => resolveModel(id, "query");
export const resolveIngestModel = (id?: string) => resolveModel(id, "ingest");

import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth/session";
import { assertScopeAllowed, canManageScope, scopeWikiPrefix } from "@/lib/acl/scope";
import { prisma } from "@/lib/db";
import { storeForAnalysis, storeRawOnly } from "@/lib/ingest";
import { extractAsset, SUPPORTED_EXTS } from "@/lib/extract";
import { CONVERT_ONLY_EXTS, libreOfficeAvailable } from "@/lib/convert";
import { currentUploadPolicy, uploadPolicyForModel, uploadPoliciesForModels } from "@/lib/uploadPolicy";
import { listQueryModels, resolveIngestModel } from "@/lib/models";
import { modelFor } from "@/lib/anthropic";

// 자료 업로드(텍스트/MD) → 인제스트 → 위키. ACL 강제지점3(인제스트 적용). docs/06·docs/07 §2.
export const runtime = "nodejs";
export const maxDuration = 300;

// GET: scope의 최근 자료 목록
export async function GET(req: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const scope = new URL(req.url).searchParams.get("scope") ?? "";
  try {
    await assertScopeAllowed(user, scope);
  } catch {
    return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
  }
  const wikiScope = scopeWikiPrefix(scope);
  // 기본은 활성(archivedAt=null)만. ?archived=1 → 아카이브된 자료(복원/영구삭제 뷰).
  const showArchived = new URL(req.url).searchParams.get("archived") === "1";
  const sources = await prisma.source.findMany({
    where: { teamScope: wikiScope, archivedAt: showArchived ? { not: null } : null },
    orderBy: { id: "desc" },
    take: 30,
    include: { ingestJobs: { orderBy: { id: "desc" }, take: 1 } },
  });
  const queryModels = await listQueryModels();
  const canManage = await canManageScope(user, wikiScope); // 아카이브·영구삭제 권한(룸 관리자)
  return NextResponse.json({
    canManage,
    sources: sources.map((s) => {
      let prov: { hasText?: boolean; looksOrganized?: boolean } = {};
      try { prov = JSON.parse(s.provenance || "{}"); } catch { /* */ }
      return {
        id: s.id,
        title: s.title,
        type: s.type,
        createdAt: s.createdAt.toISOString(),
        archived: Boolean(s.archivedAt),
        // 잡이 있으면 그 상태, 미분석 보존(UNANALYZED)이면 그대로, 그 외 잡 없는 신규 소스 = '분석 대기'(PENDING).
        status: s.ingestJobs[0]?.status ?? (s.extractStatus === "UNANALYZED" ? "UNANALYZED" : "PENDING"),
        confidence: s.ingestJobs[0]?.confidence ?? null,
        gate: s.ingestJobs[0]?.gate ?? null,
        extractStatus: s.extractStatus ?? null,
        extractor: s.extractor ?? null,
        hasExtracted: Boolean(s.normalizedPath),
        hasText: Boolean(prov.hasText ?? s.normalizedPath), // '원본 그대로' 가능 여부
        looksOrganized: Boolean(prov.looksOrganized), // 이미 위키 형식 → '원본 그대로' 추천
      };
    }),
    // LibreOffice 변환 사이드카(4j)가 켜진 환경에서만 추가 수락되는 포맷 — UI 안내·accept 확장용
    convertExts: libreOfficeAvailable() ? CONVERT_ONLY_EXTS : [],
    // 업로드 정책(기본 공급자 기준 허용 포맷·안내) — 모델 미선택 시 폴백
    policy: currentUploadPolicy(),
    // 자료 탭 모델 선택기용: 선택 가능 모델 + ★모델 id별★ 업로드 정책(선택 시 즉시 전환) + 기본 모델
    models: queryModels,
    policies: uploadPoliciesForModels(queryModels),
    defaultModel: modelFor("ingest"),
  });
}

// POST: 텍스트/MD(JSON) 또는 이미지(multipart) 1건 인제스트
export async function POST(req: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });

  // 업로드는 ★스테이징(추출·보관만, 토큰 0)★ — LLM/비용은 [분석] 버튼 시점에. (예산 체크는 analyze 라우트.)
  const ct = req.headers.get("content-type") || "";

  // 파일 업로드(multipart): 추출 레이어(docs/17)로 정규화 → 인제스트.
  // 원본 바이트는 raw로 보존(열람용), 텍스트는 파서로 추출(우선), 안 되면 네이티브 모달리티 폴백.
  if (ct.includes("multipart/form-data")) {
    const form = await req.formData();
    const scope = String(form.get("scope") || "");
    const titleField = String(form.get("title") || "");
    const file = form.get("file");
    if (!(file instanceof File)) return NextResponse.json({ error: "파일이 필요합니다." }, { status: 400 });
    try {
      await assertScopeAllowed(user, scope); // ACL 강제지점3
    } catch {
      return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
    }
    // 사용자가 자료 탭에서 고른 인제스트 모델(검증·폴백) → ★그 모델★ 능력 기준으로 게이팅·인제스트.
    const picked = await resolveIngestModel(String(form.get("model") || "") || undefined);
    const ext = (file.name.toLowerCase().match(/\.([a-z0-9]+)$/)?.[1]) || "";
    const pol = uploadPolicyForModel(picked.model, picked.provider);
    const isImg = ["image/png", "image/jpeg", "image/gif", "image/webp"].includes(file.type) || ["png", "jpg", "jpeg", "gif", "webp"].includes(ext);
    const isPdf = file.type === "application/pdf" || ext === "pdf";
    const isConvertible = libreOfficeAvailable() && CONVERT_ONLY_EXTS.includes(ext);
