/**
 * [AI로 분석] 업그레이드 보강 — '원본 그대로'(RAW_IMPORT)로 만들어졌던 topics 페이지를 분석본으로 대체한 뒤,
 * 옛 raw 페이지가 분석에 의해 갱신되지 않았다면 `.archive/`로 옮겨 중복을 없앤다(되돌리기 가능, git rm 아님).
 * analyzedPaths = 방금 analyzeSource가 쓴/생성한 경로들(changedPaths). 단일 라이터로 커밋. 대상이 없으면 no-op.
 */
export async function supersedeRawPage(sourceId: number, analyzedPaths: string[] = []): Promise<string | null> {
  const source = await prisma.source.findUnique({ where: { id: sourceId } });
  if (!source) return null;
  const scope = source.teamScope;
  const slug = slugifyTitle(source.title) || `note-${source.id}`;
  const rawRel = `${scope}/topics/${slug}.md`;
  if (analyzedPaths.includes(rawRel)) return null; // 분석이 같은 페이지를 갱신함 → 그대로 둠
  const rawAbs = wikiAbsPath(rawRel);
  try { await fs.access(rawAbs); } catch { return null; } // 옛 raw 페이지 없음 → no-op
  const destRel = `${scope}/.archive/topics/${slug}.md`;
  const destAbs = wikiAbsPath(destRel);
  await assertWikiReady();
  return withWikiWriteLock(async () => {
    await fs.mkdir(path.dirname(destAbs), { recursive: true });
    try { await fs.unlink(destAbs); } catch { /* 대상 없으면 무시(Windows rename은 기존 대상에 실패) */ }
    await fs.rename(rawAbs, destAbs);
    return commitAll(`supersede-raw(${scope}): ${rawRel} → 분석본으로 대체(아카이브)`, { team: scope, gate: "PAGE_ARCHIVED", sourceSha256: source.sha256 });
  });
}

