import { providerFor } from "./anthropic";
import { SUPPORTED_EXTS, IMG_EXT } from "./extract";
import { CONVERT_ONLY_EXTS, libreOfficeAvailable } from "./convert";
import { openaiCompatModelVision, openaiCompatDefaultModel } from "./openai-compat";

// 업로드 정책 단일 소스(PLAN-free-paid-upload-gating). 클라/서버가 같은 값을 보게
// 서버가 계산해 API로 클라에 내려준다(클라는 무거운 server-only deps를 import하지 않음).
//
// 정책은 ★선택한 모델의 능력★ 기준(공급자만으로는 부족 — 같은 Groq라도 모델별로 비전 유무가 다름):
//   - text : 약한 로컬 모델(ollama). 텍스트(.txt·.md)만.
//   - docs : 강한 텍스트 모델(Groq gpt-oss·llama-3.3 등, 비전 없음). 텍스트+PDF/오피스/한글(추출),
//            단 이미지·스캔본은 불가(비전 필요).
//   - full : 비전 모델(anthropic·gemini·Groq llama-4 등). 이미지·스캔본 포함 전체 포맷.

export type UploadTier = "text" | "docs" | "full";

export interface UploadPolicy {
  provider: string;
  tier: UploadTier;
  textOnly: boolean; // tier==="text"
  vision: boolean; // 이미지/스캔본 네이티브 처리 가능(tier==="full")
  exts: string[]; // 허용 확장자(소문자, 점 없음)
  accept: string; // <input accept>
  note: string; // UI 안내 문구
}

const TEXT_EXTS = ["txt", "md", "markdown"];
const TEXT_ACCEPT = ".txt,.md,.markdown,text/plain,text/markdown";

// 선택 모델의 업로드 티어 결정.
export function uploadTierFor(provider: string, modelId?: string): UploadTier {
  if (provider === "ollama") return "text"; // 약한 로컬
  if (provider === "openai-compat") return modelId && openaiCompatModelVision(modelId) ? "full" : "docs";
  return "full"; // anthropic, gemini (+ 알 수 없는 공급자는 안전하게 full)
}

function policyForTier(provider: string, tier: UploadTier): UploadPolicy {
  const convert = libreOfficeAvailable() ? CONVERT_ONLY_EXTS : [];
  if (tier === "text") {
    return {
      provider, tier, textOnly: true, vision: false, exts: TEXT_EXTS, accept: TEXT_ACCEPT,
      note: "무료 로컬 모델은 텍스트(.txt·.md)만 받습니다. PDF·워드·엑셀·한글·이미지는 ChatGPT 같은 AI로 '핵심만 요약한 텍스트'로 바꿔서 올려주세요(요약할수록 품질·속도가 좋아집니다).",
    };
  }
  if (tier === "docs") {
    // 텍스트 + 추출 가능한 문서(PDF·오피스·한글·CSV…), 단 이미지 확장자는 제외(비전 필요).
    const exts = [...SUPPORTED_EXTS.filter((e) => !IMG_EXT.includes(e)), ...convert];
    return {
      provider, tier, textOnly: false, vision: false, exts, accept: exts.map((e) => `.${e}`).join(","),
      note: "텍스트·PDF·워드·엑셀·한글 문서까지 분석합니다. 단 이 모델은 비전이 없어 이미지·스캔본 PDF는 불가 — 그런 자료는 Gemini나 Claude 모델을 선택해 올리세요.",
    };
  }
  const exts = [...SUPPORTED_EXTS, ...convert];
  return {
    provider, tier, textOnly: false, vision: true, exts, accept: exts.map((e) => `.${e}`).join(","),
    note: "PDF·오피스·한글·이미지까지 그대로 올리면 AI가 분석합니다.",
  };
}

// 특정 모델 기준 업로드 정책(자료 탭 모델 선택기·서버 게이팅의 단일 소스).
export function uploadPolicyForModel(modelId: string, provider: string): UploadPolicy {
  return policyForTier(provider, uploadTierFor(provider, modelId));
}

// 공급자 대표 정책(모델 미지정 시). openai-compat은 기본 모델 기준.
export function uploadPolicyFor(provider: string): UploadPolicy {
  const rep = provider === "openai-compat" ? openaiCompatDefaultModel() : undefined;
  return policyForTier(provider, uploadTierFor(provider, rep));
}

export function currentUploadPolicy(): UploadPolicy {
  return uploadPolicyFor(providerFor("ingest"));
}

// 모델 선택기용 — 모델 id별 정책 묶음(클라가 선택 모델에 맞춰 즉시 전환).
export function uploadPoliciesForModels(models: { id: string; provider: string }[]): Record<string, UploadPolicy> {
  const out: Record<string, UploadPolicy> = {};
  for (const m of models) out[m.id] = uploadPolicyForModel(m.id, m.provider);
  return out;
}

export function extOf(filename: string): string {
  return filename.toLowerCase().match(/\.([a-z0-9]+)$/)?.[1] ?? "";
}

export function isAllowedUpload(filename: string, pol: UploadPolicy = currentUploadPolicy()): boolean {
  return pol.exts.includes(extOf(filename));
}

