864:.mat-switch-note { display: flex; align-items: center; gap: 6px; font-size: 11.5px; line-height: 1.45; color: var(--color-text-secondary); background: var(--color-background-secondary); border: 1px solid var(--color-border-tertiary); border-radius: var(--border-radius-sm); padding: 6px 10px; margin-bottom: 8px; }
865:.mat-switch-note svg { flex-shrink: 0; color: var(--color-accent); }
866:.mat-switch-note b { color: var(--color-text-primary); font-weight: 600; }
