898:.mat-status.pend { background: color-mix(in srgb, var(--color-accent) 14%, transparent); color: var(--color-accent); }
900:.mat-mode { display: flex; gap: 8px; margin-bottom: 10px; }
901:.mat-mode-btn { flex: 1; display: flex; flex-direction: column; align-items: flex-start; gap: 2px; padding: 8px 11px; border: 1px solid var(--color-border-secondary); border-radius: var(--border-radius-md); background: var(--color-background-primary); color: var(--color-text-secondary); font-size: 12.5px; font-weight: var(--weight-medium); cursor: pointer; text-align: left; }
902:.mat-mode-btn:hover:not(:disabled) { border-color: var(--color-accent); }
903:.mat-mode-btn.on { border-color: var(--color-accent); background: color-mix(in srgb, var(--color-accent) 8%, transparent); color: var(--color-accent); }
904:.mat-mode-btn:disabled { opacity: .6; cursor: default; }
905:.mat-mode-sub { font-size: 10.5px; font-weight: var(--weight-regular); color: var(--color-text-tertiary); }
906:.mat-mode-btn.on .mat-mode-sub { color: var(--color-accent); }
909:.mat-run { border: 1px solid var(--color-border-secondary); background: var(--color-background-primary); color: var(--color-text-secondary); font-size: 11px; font-weight: var(--weight-medium); padding: 3px 8px; border-radius: 99px; cursor: pointer; white-space: nowrap; flex-shrink: 0; }
910:.mat-run:hover { border-color: var(--color-accent); color: var(--color-accent); }
916:.mat-open, .mat-act { border: none; background: none; color: var(--color-text-tertiary); cursor: pointer; padding: 4px; border-radius: var(--border-radius-sm); flex-shrink: 0; display: flex; text-decoration: none; }
917:.mat-open:hover, .mat-act:hover { background: var(--color-background-secondary); color: var(--color-accent); }
937:.mat-queue { margin-top: 12px; border: 1px solid var(--color-border-tertiary); border-radius: var(--border-radius-md); overflow: hidden; }
938:.mat-queue-head { padding: 6px 11px; font-size: 11.5px; color: var(--color-text-secondary); background: var(--color-background-secondary); border-bottom: 1px solid var(--color-border-tertiary); }
939:.mat-queue-item { display: flex; align-items: center; gap: 8px; padding: 7px 11px; font-size: 12px; border-bottom: 1px solid var(--color-border-tertiary); }
940:.mat-queue-item:last-child { border-bottom: none; }
942:.mat-queue-item.running .mq-dot { background: var(--color-accent); animation: mq-pulse 1s ease-in-out infinite; }
943:.mat-queue-item.done .mq-dot { background: var(--color-text-success); }
944:.mat-queue-item.error .mq-dot { background: var(--color-text-danger); }
948:.mat-queue-item.error .mq-status { color: var(--color-text-danger); }
949:.mat-queue-item.done .mq-status { color: var(--color-text-success); }
950:.mat-del { border: none; background: none; color: var(--color-text-tertiary); cursor: pointer; padding: 4px; border-radius: var(--border-radius-sm); flex-shrink: 0; display: flex; }
951:.mat-del:hover { background: var(--color-background-danger); color: var(--color-text-danger); }
952:.mat-del:disabled { opacity: .5; cursor: not-allowed; }

input.content:
"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import {
  IconUpload, IconFileText, IconCircleCheck, IconAlertTriangle, IconClockHour4,
  IconChevronRight, IconTrash, IconCalendar, IconExternalLink, IconArrowUpRight, IconArticle,
  IconArrowsExchange, IconArchive, IconArrowBackUp, IconTrashX, IconSparkles, IconInfoCircle,
} from "@tabler/icons-react";
import { typeIcon } from "./fileIcons";

function SourceGroup({ ym, items, onArchive, onWiki, onRecover, onAnalyze, analyzeReason, onRestore, onPurge, deleting, acting, notes, canManage, archivedMode }: {
  ym: string; items: SourceItem[]; onArchive: (s: SourceItem) => void; onWiki: (s: SourceItem) => void;
  onRecover: (s: SourceItem) => void; onAnalyze: (s: SourceItem) => void; analyzeReason?: string;
  onRestore?: (s: SourceItem) => void; onPurge?: (s: SourceItem) => void;
  deleting: number | null; acting: Set<number>; notes: Record<number, string>; canManage: boolean; archivedMode?: boolean;
}) {
  const [open, setOpen] = useState(true);
  return (
    <div>
      <button className="mat-group" onClick={() => setOpen((o) => !o)}>
        <IconChevronRight size={13} className={`tree-caret${open ? " open" : ""}`} />
        <IconCalendar size={14} />{ym}<span className="mat-group-count">({items.length})</span>
      </button>
      {open && items.map((s) => {
        const FIcon = typeIcon(s.type);
        // 정상 흐름은 업로드 박스에서 처리됨. 여기 PENDING/FAILED는 업로드 중 이탈 등으로 남은 '잔여' → 재처리 복구만.
        const stuck = s.status === "PENDING" || s.status === "FAILED";
        const isRaw = s.status === "APPLIED" && s.gate === "RAW_IMPORT"; // '원본 그대로' 보관 — 아직 분석 안 됨
        // [AI로 분석] 대상: 원본 그대로 보관본 + 미분석 보존본(엔티티/개념에 반영하려면).
        const canAnalyze = !archivedMode && (isRaw || s.status === "UNANALYZED");
        const busy = acting.has(s.id);
        const note = notes[s.id];
        return (
          <div key={s.id} className="mat-item tree">
            <FIcon size={17} className="mat-ficon" />
            <div className="mat-item-main">
              <div className="mat-item-title" title={s.title}>{s.title}</div>
              <div className="mat-item-sub"><span className="mat-ext">{s.type}</span> · {s.createdAt.slice(0, 10)}</div>
              {note && <div className="mat-item-note">{note}</div>}
            </div>
            {!archivedMode && (
              <span className={`mat-status ${s.status === "APPLIED" ? (isRaw ? "muted" : "ok") : s.status === "FAILED" ? "err" : s.status === "UNANALYZED" ? "warn" : s.status === "PENDING" ? "pend" : "muted"}`}>
                {busy ? "처리 중…" : s.status === "APPLIED" ? (isRaw ? "원본 보관" : "반영됨") : s.status === "FAILED" ? "실패" : s.status === "SKIPPED_DUP" ? "중복" : s.status === "UNANALYZED" ? "미분석" : s.status === "PENDING" ? "분석 대기" : s.status ?? "-"}
              </span>
            )}
            <div className="mat-acts">
              <a className="mat-act" href={`/api/materials/${s.id}/raw`} target="_blank" rel="noreferrer" title="원본 열기"><IconExternalLink size={13} /></a>
              {archivedMode ? (
                <>
                  <button className="mat-act" disabled={busy} onClick={() => onRestore!(s)} title="복원"><IconArrowBackUp size={14} /></button>
                  <button className="mat-del" disabled={deleting === s.id || busy} onClick={() => onPurge!(s)} title="영구삭제"><IconTrashX size={14} /></button>
                </>
              ) : (
                <>
                  {stuck && !busy && <button className="mat-run" onClick={() => onRecover(s)} title="이 자료를 (위쪽에서 고른 방식으로) 다시 처리">재처리</button>}
                  {canAnalyze && !busy && (
                    <button className="mat-run mat-analyze" onClick={() => onAnalyze(s)} title={analyzeReason || "AI로 분석해 엔티티·개념에 반영하고 다른 자료와 연결합니다"}>
                      <IconSparkles size={12} />AI로 분석
                    </button>
                  )}
                  {!stuck && <button className="mat-act" onClick={() => onWiki(s)} title="위키 페이지로 이동"><IconArrowUpRight size={13} /></button>}
                  {s.hasExtracted && (
                    <a className="mat-act" href={`/api/materials/${s.id}/extracted`} target="_blank" rel="noreferrer" title="추출본(읽은 텍스트)"><IconArticle size={13} /></a>
                  )}
                  {canManage && <button className="mat-del" disabled={deleting === s.id || busy} onClick={() => onArchive(s)} title="아카이브(삭제)"><IconTrash size={13} /></button>}
                </>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

interface SourceItem { id: number; title: string; type: string; createdAt: string; status: string | null; confidence: number | null; gate: string | null; extractStatus?: string | null; extractor?: string | null; hasExtracted?: boolean; hasText?: boolean; looksOrganized?: boolean; archived?: boolean }
interface UploadPolicy { provider: string; tier?: string; textOnly: boolean; vision?: boolean; exts: string[]; accept: string; note: string }
interface AnalyzeModel { model: string; provider: string; label: string; reason: string }
// 스테이징(보관됨)된 한 파일/입력 — 사용자가 [처리 시작]을 누르기 전까지 대기.
interface Staged { key: number; sourceId: number | null; name: string; hasText: boolean; status: "staging" | "staged" | "running" | "done" | "error" | "skip"; note?: string }

const extOf = (n: string) => n.toLowerCase().match(/\.([a-z0-9]+)$/)?.[1] ?? "";

// 업로드 원본을 연-월(YYYY-MM)로 묶어 최신순 트리로.
function groupByMonth(sources: SourceItem[]): [string, SourceItem[]][] {
  const m = new Map<string, SourceItem[]>();
  for (const s of sources) {
    const k = s.createdAt.slice(0, 7);
    const arr = m.get(k);
    if (arr) arr.push(s); else m.set(k, [s]);
  }
  return [...m.entries()].sort((a, b) => b[0].localeCompare(a[0]));
}

export default function MaterialsTab({ scope, hidden, onOpenWiki, dataRev, onDataChanged }: {
  scope: string; hidden?: boolean; onOpenWiki: (path: string) => void; modelsRev?: number; dataRev?: number; onDataChanged?: () => void;
}) {
  const [title, setTitle] = useState("");
  const [text, setText] = useState("");
  const [busy, setBusy] = useState(false); // [처리 시작] 진행 중(전체 직렬)
  const [err, setErr] = useState<string | null>(null);
  const [uploadMode, setUploadMode] = useState<"llm" | "raw">("llm"); // 처리 방식(확정 시 적용)
  const [staged, setStaged] = useState<Staged[]>([]); // 대기(스테이징)된 항목
  const [sources, setSources] = useState<SourceItem[]>([]);
  const [deleting, setDeleting] = useState<number | null>(null);
  const [delNote, setDelNote] = useState<string | null>(null);
  const [canManage, setCanManage] = useState(false); // 아카이브·영구삭제 권한(룸 관리자)
  const [archivedSources, setArchivedSources] = useState<SourceItem[]>([]);
  const [showArchived, setShowArchived] = useState(false);
  const [convertExts, setConvertExts] = useState<string[]>([]);
  const [policy, setPolicy] = useState<UploadPolicy | null>(null);
  const [analyzeModel, setAnalyzeModel] = useState<AnalyzeModel | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const [acting, setActing] = useState<Set<number>>(new Set()); // 분석/원본그대로 처리 중인 소스 id
  const [notes, setNotes] = useState<Record<number, string>>({}); // 처리 결과 메모(자동전환·반영 등)
  const fileRef = useRef<HTMLInputElement>(null);

  const load = useCallback(async () => {
    try {
      const res = await fetch(`/api/materials?scope=${encodeURIComponent(scope)}`, { cache: "no-store" });
      const d = await res.json();
      if (res.ok) {
        setSources(d.sources); setConvertExts(d.convertExts || []); setPolicy(d.policy || null);
        setCanManage(Boolean(d.canManage)); setAnalyzeModel(d.analyzeModel || null);
      }
    } catch { /* noop */ }
  }, [scope]);

  // 아카이브된 자료 목록(복원/영구삭제 뷰) — 별도 조회(?archived=1).
  const loadArchived = useCallback(async () => {
    try {
      const res = await fetch(`/api/materials?scope=${encodeURIComponent(scope)}&archived=1`, { cache: "no-store" });
      const d = await res.json();
      if (res.ok) setArchivedSources(d.sources || []);
    } catch { /* noop */ }
  }, [scope]);

  useEffect(() => { setSources([]); setStaged([]); setErr(null); setDelNote(null); setArchivedSources([]); setShowArchived(false); load(); }, [scope, load]);

  // 교차 갱신: 위키 배너에서 [AI로 분석]하거나 다른 경로로 데이터가 바뀌면 목록 재조회(초기 마운트는 건너뜀).
  const firstRev = useRef(true);
  useEffect(() => {
    if (firstRev.current) { firstRev.current = false; return; }
    load(); if (showArchived) loadArchived();
  }, [dataRev]); // eslint-disable-line react-hooks/exhaustive-deps

  async function openWiki(s: SourceItem) {
    try {
      const res = await fetch(`/api/materials/${s.id}/pages`);
      const d = await res.json();
      if (res.ok && d.paths?.length) onOpenWiki(d.paths[0]);
      else setDelNote(`「${s.title}」에서 생성된 위키 페이지를 찾지 못했습니다.`);
    } catch {
      setDelNote("위키 페이지를 찾지 못했습니다.");
    }
  }

  // 자료 아카이브(소프트 삭제) — 목록에서 숨기고 아카이브로. 원본·위키 페이지는 보존. 룸 관리자만.
  async function archiveSource(s: SourceItem) {
    if (!confirm(`원본 「${s.title}」을(를) 아카이브할까요?\n목록에서 숨겨지며, 아카이브에서 복원하거나 영구삭제할 수 있습니다. (위키 페이지는 그대로 유지됩니다)`)) return;
    setDeleting(s.id); setDelNote(null);
    try {
      const res = await fetch(`/api/materials/${s.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "archive" }) });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error || "아카이브에 실패했습니다.");
      setDelNote(`「${s.title}」 아카이브됨`);
      await Promise.all([load(), loadArchived()]);
    } catch (e) {
      setDelNote(`오류: ${e instanceof Error ? e.message : String(e)}`);
    } finally {
      setDeleting(null);
    }
  }

  // 아카이브에서 복원 — 다시 활성 목록으로.
  async function restoreSource(s: SourceItem) {
    setDeleting(s.id); setDelNote(null);
    try {
      const res = await fetch(`/api/materials/${s.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "restore" }) });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error || "복원에 실패했습니다.");
      setDelNote(`「${s.title}」 복원됨`);
      await Promise.all([load(), loadArchived()]);
    } catch (e) {
      setDelNote(`오류: ${e instanceof Error ? e.message : String(e)}`);
    } finally {
      setDeleting(null);
    }
  }

  // 영구삭제 — 원본·사이드카 제거 + 인용 위키 페이지에 '출처 소실' 표시. 되돌릴 수 없음.
  async function purgeSource(s: SourceItem) {
    if (!confirm(`원본 「${s.title}」을(를) 영구삭제할까요? 되돌릴 수 없습니다.\n매핑된 위키 페이지는 보존되며 '출처 소실' 표시가 남습니다.`)) return;
    setDeleting(s.id); setDelNote(null);
    try {
      const res = await fetch(`/api/materials/${s.id}`, { method: "DELETE" });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error || "삭제에 실패했습니다.");
      setDelNote(`「${s.title}」 영구삭제됨 · 위키 ${d.annotated}곳에 출처 소실 표시`);
      await Promise.all([load(), loadArchived()]);
      onDataChanged?.(); // 위키 페이지에 흔적 → 트리/리더 갱신
    } catch (e) {
      setDelNote(`오류: ${e instanceof Error ? e.message : String(e)}`);
    } finally {
      setDeleting(null);
    }
  }

  // 파일 선택/드롭 → ★스테이징만★(자동 처리 안 함). 사용자가 모드 고르고 [처리 시작]을 눌러야 인제스트.
  function onPickFile(e: React.ChangeEvent<HTMLInputElement>) {
    const files = e.target.files ? [...e.target.files] : [];
    e.target.value = "";
    if (files.length) void stageFiles(files);
  }
  function onDrop(e: React.DragEvent) {
    e.preventDefault();
    setDragOver(false);
    const files = e.dataTransfer?.files ? [...e.dataTransfer.files] : [];
    if (files.length) void stageFiles(files);
  }

  // 스테이징 결과 해석: 중복/미분석은 더 처리할 수 없으니 'skip'(완료), 그 외는 'staged'(처리 대기).
  function toStaged(prev: Staged, data: { status?: string; sourceId?: number; hasText?: boolean; unanalyzed?: boolean }): Staged {
    if (data.status === "SKIPPED_DUP") return { ...prev, status: "skip", note: "중복(건너뜀)" };
    if (data.unanalyzed || !data.sourceId) return { ...prev, status: "skip", note: "원본 보존(미분석)" };
    return { ...prev, status: "staged", sourceId: data.sourceId, hasText: !!data.hasText };
  }

  // 파일을 스테이징(추출·보관만, 토큰 0). 허용 안 되는 확장자는 에러로 표시.
  async function stageFiles(files: File[]) {
    const allowExt = (n: string) => !policy || policy.exts.includes(extOf(n));
    const ok = files.filter((f) => allowExt(f.name));
    const blocked = files.filter((f) => !allowExt(f.name));
    setErr(null);
    const base = Date.now();
    setStaged((prev) => [
      ...prev,
      ...blocked.map((f, i) => ({ key: base + 9000 + i, sourceId: null, name: f.name, hasText: false, status: "error" as const, note: policy?.note || "지원하지 않는 형식" })),
      ...ok.map((f, i) => ({ key: base + i, sourceId: null, name: f.name, hasText: false, status: "staging" as const })),
    ]);
    const single = ok.length === 1 ? (title.trim() || undefined) : undefined;
    for (let i = 0; i < ok.length; i++) {
      const key = base + i;
      try {
        const fd = new FormData();
        fd.append("scope", scope);
        if (single) fd.append("title", single);
        fd.append("file", ok[i]);
        const res = await fetch("/api/materials", { method: "POST", body: fd }); // 모델 미전송 → 서버가 자동 모델 기준 게이팅
        const data = await res.json();
        if (!res.ok) { setStaged((p) => p.map((x) => (x.key === key ? { ...x, status: "error", note: data.error || "업로드 실패" } : x))); continue; }
        setStaged((p) => p.map((x) => (x.key === key ? toStaged(x, data) : x)));
      } catch (e) {
        setStaged((p) => p.map((x) => (x.key === key ? { ...x, status: "error", note: e instanceof Error ? e.message : String(e) } : x)));
      }
    }
    if (single) setTitle("");
  }

  // 직접 입력 텍스트를 스테이징(대기열에 추가).
  async function stageText() {
    if (busy || !text.trim()) return;
    setErr(null);
    const key = Date.now();
    const name = title.trim() || text.trim().split("\n")[0].slice(0, 40) || "직접 입력";
    setStaged((prev) => [...prev, { key, sourceId: null, name, hasText: true, status: "staging" }]);
    try {
      const res = await fetch("/api/materials", {
        method: "POST", headers: { "content-type": "application/json" },
        body: JSON.stringify({ scope, title: title.trim() || undefined, text }),
      });
      const data = await res.json();
      if (!res.ok) { setStaged((p) => p.map((x) => (x.key === key ? { ...x, status: "error", note: data.error || "추가 실패" } : x))); return; }
      setStaged((p) => p.map((x) => (x.key === key ? toStaged(x, data) : x)));
      setText(""); setTitle("");
    } catch (e) {
      setStaged((p) => p.map((x) => (x.key === key ? { ...x, status: "error", note: e instanceof Error ? e.message : String(e) } : x)));
    }
  }

  // 스테이징된 소스를 ★선택한 모드★로 처리. raw는 텍스트가 있을 때만, 없으면(PDF·이미지) 자동으로 llm.
  async function runProcess(sourceId: number, hasText: boolean): Promise<{ ok: boolean; note: string }> {
    const fellBack = uploadMode === "raw" && !hasText;
    const effMode = uploadMode === "raw" && hasText ? "raw" : "llm";
    const body = effMode === "raw" ? { mode: "raw" } : { mode: "llm" }; // llm은 모델 미지정 → 서버 자동 선택
    const res = await fetch(`/api/materials/${sourceId}/analyze`, {
      method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body),
    });
    const data = await res.json();
    if (!res.ok) return { ok: false, note: `처리 실패: ${data.error || ""}` };
    if (effMode === "raw") return { ok: true, note: "원본 그대로 추가됨 · 토큰 0" };
    const sw = data.fallback ? " · 백업 모델로 자동 전환됨" : "";
    const prefix = fellBack ? "텍스트 없음 → 분석함 · " : "";
    const base = data.status === "NEEDS_REVIEW" ? "검토 대기" : "분석 반영됨";
    return { ok: true, note: prefix + base + sw };
  }

  // [처리 시작] — 대기(staged) 항목을 순차 처리(위키는 단일 라이터). 끝나면 목록·트리 갱신.
  async function runStaged() {
    if (busy) return;
    const todo = staged.filter((s) => s.status === "staged" && s.sourceId);
    if (!todo.length) return;
    setBusy(true); setErr(null);
    for (const it of todo) {
      setStaged((p) => p.map((x) => (x.key === it.key ? { ...x, status: "running", note: uploadMode === "raw" ? "추가 중…" : "분석 중…" } : x)));
      const r = await runProcess(it.sourceId!, it.hasText);
      setStaged((p) => p.map((x) => (x.key === it.key ? { ...x, status: r.ok ? "done" : "error", note: r.note } : x)));
    }
    setBusy(false);
    await load();
    onDataChanged?.(); // 위키 트리/리더 갱신(③)
  }

  function clearStaged() { setStaged([]); }

  // 잔여(PENDING/FAILED) 복구 — 업로드 중 이탈 등으로 남은 항목을 현재 모드로 다시 처리.
  async function recover(s: SourceItem) {
    if (acting.has(s.id)) return;
    setActing((a) => new Set(a).add(s.id));
    setNotes((n) => { const c = { ...n }; delete c[s.id]; return c; });
    try {
      const r = await runProcess(s.id, !!s.hasText);
      setNotes((n) => ({ ...n, [s.id]: r.note }));
    } catch (e) {
      setNotes((n) => ({ ...n, [s.id]: `오류: ${e instanceof Error ? e.message : String(e)}` }));
    } finally {
      setActing((a) => { const c = new Set(a); c.delete(s.id); return c; });
      await load(); onDataChanged?.();
    }
  }

  // [AI로 분석] — '원본 그대로'/'미분석' 자료를 ★자동 모델★로 분석해 엔티티·개념에 반영(옛 raw 페이지는 서버가 대체).
  async function analyzeItem(s: SourceItem) {
    if (acting.has(s.id)) return;
    setActing((a) => new Set(a).add(s.id));
    setNotes((n) => { const c = { ...n }; delete c[s.id]; return c; });
    try {
      const res = await fetch(`/api/materials/${s.id}/analyze`, {
        method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ mode: "llm" }),
      });
      const data = await res.json();
      if (!res.ok) setNotes((n) => ({ ...n, [s.id]: `분석 실패: ${data.error || ""}` }));
      else {
        const sw = data.fallback ? " · 백업 모델로 자동 전환됨" : "";
        setNotes((n) => ({ ...n, [s.id]: (data.status === "NEEDS_REVIEW" ? "검토 대기" : "AI 분석 반영됨") + sw }));
      }
    } catch (e) {
      setNotes((n) => ({ ...n, [s.id]: `오류: ${e instanceof Error ? e.message : String(e)}` }));
    } finally {
      setActing((a) => { const c = new Set(a); c.delete(s.id); return c; });
      await load(); onDataChanged?.(); // 새 엔티티/개념 페이지 → 위키 트리/리더 갱신
    }
  }

  const provider = analyzeModel?.provider;
  const external = uploadMode === "llm" && (provider === "gemini" || provider === "openai-compat");
  const procCount = staged.filter((s) => s.status === "staged" && s.sourceId).length;
  const accept = policy?.accept ?? (".md,.markdown,.txt,.csv,.html,.htm,.json,.pdf,.docx,.doc,.xlsx,.xls,.pptx,.odt,.ods,.odp,.rtf,.hwp,.hwpx,.png,.jpg,.jpeg,.gif,.webp" + convertExts.map((e) => `,.${e}`).join(""));

  return (
    <div className={`mat-wrap${hidden ? " hidden" : ""}`}>
      <div className="mat-col mat-col-upload">
        <div className="mat-card">
          <div className="mat-card-head"><IconUpload size={15} />자료 추가</div>
          <p className="mat-desc">
            올리면 먼저 <b>대기 목록</b>에 담깁니다. 처리 방식을 고르고 <b>[처리 시작]</b>을 눌러야 위키에 반영됩니다. 원본은 항상 그대로 보관됩니다.
          </p>

          {/* 처리 방식 선택 — 분석(엔티티·개념 연결) vs 원본 그대로(토큰 0 보관) */}
          <div className="mat-mode">
            <button type="button" className={`mat-mode-btn${uploadMode === "llm" ? " on" : ""}`} disabled={busy} onClick={() => setUploadMode("llm")}>
              분석해서 추가<span className="mat-mode-sub">엔티티·개념에 반영 · 다른 자료와 연결</span>
            </button>
            <button type="button" className={`mat-mode-btn${uploadMode === "raw" ? " on" : ""}`} disabled={busy} onClick={() => setUploadMode("raw")}>
              원본 그대로 추가<span className="mat-mode-sub">topics에 그대로 보관 · 토큰 0 · 연결 안 됨</span>
            </button>
          </div>

          {/* 분석 모델은 ★자동 선택★ — 사용자가 고르지 않는다. ⓘ 툴팁에 사유. */}
          {uploadMode === "llm" && analyzeModel && (
            <div className="mat-automodel" title={analyzeModel.reason}>
              <IconSparkles size={13} />
              <span>분석 모델 <b>{analyzeModel.label}</b> 자동 선택</span>
              <IconInfoCircle size={13} className="mat-automodel-info" />
            </div>
          )}

          {uploadMode === "raw" && (
            <div className="mat-switch-note"><IconArrowsExchange size={13} />
              <span>분석 없이 원본을 그대로 위키에 보관합니다(<b>토큰 0</b>). 엔티티·개념엔 정리되지 않으니, 연결이 필요하면 <b>분석해서 추가</b>를 쓰거나 나중에 목록에서 <b>AI로 분석</b>을 누르세요. (텍스트 없는 PDF·이미지는 자동으로 분석됩니다.)</span>
            </div>
          )}

          {external && (
            <div className="gemini-warn"><IconAlertTriangle size={13} />
              <span>{provider === "gemini"
                ? <>Gemini(외부)는 빠르지만 <b>올린 자료가 Google로 전송·학습</b>됩니다. <br />민감 자료는 올리지 마세요.</>
                : <>이 모델(외부)은 빠르지만 <b>올린 자료가 외부 서버로 전송</b>됩니다. <br />민감 자료는 올리지 마세요.</>}</span>
            </div>
          )}

          <div className={`mat-drop${busy ? " busy" : ""}${dragOver ? " dragover" : ""}`}
            onClick={() => { if (!busy) fileRef.current?.click(); }}
            onDragOver={(e) => { e.preventDefault(); if (!busy) setDragOver(true); }}
            onDragLeave={() => setDragOver(false)}
            onDrop={onDrop}>
            <IconUpload size={20} />
            <span><b>{policy?.textOnly ? "텍스트 파일(.txt·.md)을 끌어다 놓거나" : "파일을 끌어다 놓거나"}</b> 클릭해 선택 <span className="mat-multi">(여러 개 가능 · 대기 목록에 담김)</span></span>
            <input ref={fileRef} type="file" hidden multiple disabled={busy} accept={accept} onChange={onPickFile} />
          </div>
          <div className={`mat-formats${policy?.textOnly ? " mat-formats-note" : ""}`}>
            {policy?.note ?? "지원 형식: 텍스트(.md .txt) · PDF · 이미지 · 한글 · Word · Excel · PowerPoint · 오픈오피스 · RTF · HTML"}
          </div>

          <div className="mat-or">또는 직접 입력</div>
          <input className="mat-input" placeholder="제목 (단건 업로드/직접 입력 시, 비우면 자동)" value={title} maxLength={80} onChange={(e) => setTitle(e.target.value)} />
          <textarea className="mat-input mat-textarea" placeholder="여기에 내용을 붙여넣으세요…" value={text} onChange={(e) => setText(e.target.value)} />
          <button className="mat-stage-add" onClick={stageText} disabled={busy || !text.trim()}>대기 목록에 추가</button>

          {/* 대기(스테이징) 목록 */}
          {staged.length > 0 && (
            <div className="mat-queue">
              <div className="mat-queue-head">대기 {staged.filter((u) => u.status === "done" || u.status === "skip").length}/{staged.length} 처리됨</div>
              {staged.map((u) => {
                const cls = u.status === "running" || u.status === "staging" ? "running" : u.status === "error" ? "error" : u.status === "staged" ? "pending" : "done";
                const label = u.status === "staging" ? "올리는 중…" : u.status === "staged" ? "대기" : u.status === "running" ? (u.note || "처리 중…") : u.status === "error" ? `실패: ${u.note || ""}` : (u.note || "완료");
                return (
                  <div key={u.key} className={`mat-queue-item ${cls}`}>
                    <span className="mq-dot" />
                    <span className="mq-name" title={u.name}>{u.name}</span>
                    <span className="mq-status">{label}</span>
                  </div>
                );
              })}
            </div>
          )}

          {err && <div className="mat-banner err"><IconAlertTriangle size={14} />{err}</div>}

          <button className="mat-submit" onClick={runStaged} disabled={busy || procCount === 0}>
            {busy ? <><IconClockHour4 size={14} />{uploadMode === "raw" ? "추가 중…" : "분석 중…"}</> : (
              procCount === 0 ? "처리 시작 (대기 항목 없음)" : `${uploadMode === "raw" ? "원본 그대로 추가" : "분석해서 추가"} (${procCount}개)`
            )}
          </button>
          {staged.length > 0 && !busy && (
            <button className="mat-stage-clear" onClick={clearStaged}>대기 목록 비우기</button>
          )}
        </div>
      </div>

      <div className="mat-col mat-col-list">
        <div className="mat-card">
          <div className="mat-card-head"><IconFileText size={15} />최근 자료 {sources.length > 0 && `(${sources.length})`}</div>
          {delNote && <div className="mat-banner muted" style={{ marginBottom: 10 }}>{delNote}</div>}
          {sources.length === 0 ? (
            <p className="mat-desc">아직 올린 자료가 없습니다.</p>
          ) : (
            <div className="mat-tree">
              {groupByMonth(sources).map(([ym, items]) => (
                <SourceGroup key={ym} ym={ym} items={items} onArchive={archiveSource} onWiki={openWiki}
                  onRecover={recover} onAnalyze={analyzeItem} analyzeReason={analyzeModel?.reason}
                  deleting={deleting} acting={acting} notes={notes} canManage={canManage} />
              ))}
            </div>
          )}

          {/* 아카이브(소프트 삭제) 섹션 — 룸 관리자만. 펼칠 때 조회. */}
          {canManage && (
            <div className="mat-archive">
              <button className="mat-archive-head" onClick={() => { const n = !showArchived; setShowArchived(n); if (n) loadArchived(); }}>
                <IconChevronRight size={13} className={`tree-caret${showArchived ? " open" : ""}`} />
                <IconArchive size={14} />아카이브{archivedSources.length > 0 ? ` (${archivedSources.length})` : ""}
              </button>
              {showArchived && (
                archivedSources.length === 0 ? (
                  <p className="mat-desc mat-archive-empty">아카이브된 자료가 없습니다.</p>
                ) : (
                  <div className="mat-tree">
                    {groupByMonth(archivedSources).map(([ym, items]) => (
                      <SourceGroup key={ym} ym={ym} items={items} archivedMode canManage={canManage}
                        onArchive={archiveSource} onWiki={openWiki} onRecover={recover} onAnalyze={analyzeItem}
                        onRestore={restoreSource} onPurge={purgeSource}
                        deleting={deleting} acting={acting} notes={notes} />
                    ))}
                  </div>
                )
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

toolUseResult.content:
"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import {
  IconUpload, IconFileText, IconCircleCheck, IconAlertTriangle, IconClockHour4,
  IconChevronRight, IconTrash, IconCalendar, IconExternalLink, IconArrowUpRight, IconArticle,
  IconArrowsExchange, IconArchive, IconArrowBackUp, IconTrashX, IconSparkles, IconInfoCircle,
} from "@tabler/icons-react";
import { typeIcon } from "./fileIcons";

function SourceGroup({ ym, items, onArchive, onWiki, onRecover, onAnalyze, analyzeReason, onRestore, onPurge, deleting, acting, notes, canManage, archivedMode }: {
  ym: string; items: SourceItem[]; onArchive: (s: SourceItem) => void; onWiki: (s: SourceItem) => void;
  onRecover: (s: SourceItem) => void; onAnalyze: (s: SourceItem) => void; analyzeReason?: string;
  onRestore?: (s: SourceItem) => void; onPurge?: (s: SourceItem) => void;
  deleting: number | null; acting: Set<number>; notes: Record<number, string>; canManage: boolean; archivedMode?: boolean;
}) {
  const [open, setOpen] = useState(true);
  return (
    <div>
      <button className="mat-group" onClick={() => setOpen((o) => !o)}>
        <IconChevronRight size={13} className={`tree-caret${open ? " open" : ""}`} />
        <IconCalendar size={14} />{ym}<span className="mat-group-count">({items.length})</span>
      </button>
      {open && items.map((s) => {
        const FIcon = typeIcon(s.type);
        // 정상 흐름은 업로드 박스에서 처리됨. 여기 PENDING/FAILED는 업로드 중 이탈 등으로 남은 '잔여' → 재처리 복구만.
        const stuck = s.status === "PENDING" || s.status === "FAILED";
        const isRaw = s.status === "APPLIED" && s.gate === "RAW_IMPORT"; // '원본 그대로' 보관 — 아직 분석 안 됨
        // [AI로 분석] 대상: 원본 그대로 보관본 + 미분석 보존본(엔티티/개념에 반영하려면).
        const canAnalyze = !archivedMode && (isRaw || s.status === "UNANALYZED");
        const busy = acting.has(s.id);
        const note = notes[s.id];
        return (
          <div key={s.id} className="mat-item tree">
            <FIcon size={17} className="mat-ficon" />
            <div className="mat-item-main">
              <div className="mat-item-title" title={s.title}>{s.title}</div>
              <div className="mat-item-sub"><span className="mat-ext">{s.type}</span> · {s.createdAt.slice(0, 10)}</div>
              {note && <div className="mat-item-note">{note}</div>}
            </div>
            {!archivedMode && (
              <span className={`mat-status ${s.status === "APPLIED" ? (isRaw ? "muted" : "ok") : s.status === "FAILED" ? "err" : s.status === "UNANALYZED" ? "warn" : s.status === "PENDING" ? "pend" : "muted"}`}>
                {busy ? "처리 중…" : s.status === "APPLIED" ? (isRaw ? "원본 보관" : "반영됨") : s.status === "FAILED" ? "실패" : s.status === "SKIPPED_DUP" ? "중복" : s.status === "UNANALYZED" ? "미분석" : s.status === "PENDING" ? "분석 대기" : s.status ?? "-"}
              </span>
            )}
            <div className="mat-acts">
              <a className="mat-act" href={`/api/materials/${s.id}/raw`} target="_blank" rel="noreferrer" title="원본 열기"><IconExternalLink size={13} /></a>
              {archivedMode ? (
                <>
                  <button className="mat-act" disabled={busy} onClick={() => onRestore!(s)} title="복원"><IconArrowBackUp size={14} /></button>
                  <button className="mat-del" disabled={deleting === s.id || busy} onClick={() => onPurge!(s)} title="영구삭제"><IconTrashX size={14} /></button>
                </>
              ) : (
                <>
                  {stuck && !busy && <button className="mat-run" onClick={() => onRecover(s)} title="이 자료를 (위쪽에서 고른 방식으로) 다시 처리">재처리</button>}
                  {canAnalyze && !busy && (
                    <button className="mat-run mat-analyze" onClick={() => onAnalyze(s)} title={analyzeReason || "AI로 분석해 엔티티·개념에 반영하고 다른 자료와 연결합니다"}>
                      <IconSparkles size={12} />AI로 분석
                    </button>
                  )}
                  {!stuck && <button className="mat-act" onClick={() => onWiki(s)} title="위키 페이지로 이동"><IconArrowUpRight size={13} /></button>}
                  {s.hasExtracted && (
                    <a className="mat-act" href={`/api/materials/${s.id}/extracted`} target="_blank" rel="noreferrer" title="추출본(읽은 텍스트)"><IconArticle size={13} /></a>
                  )}
                  {canManage && <button className="mat-del" disabled={deleting === s.id || busy} onClick={() => onArchive(s)} title="아카이브(삭제)"><IconTrash size={13} /></button>}
                </>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

interface SourceItem { id: number; title: string; type: string; createdAt: string; status: string | null; confidence: number | null; gate: string | null; extractStatus?: string | null; extractor?: string | null; hasExtracted?: boolean; hasText?: boolean; looksOrganized?: boolean; archived?: boolean }
interface UploadPolicy { provider: string; tier?: string; textOnly: boolean; vision?: boolean; exts: string[]; accept: string; note: string }
interface AnalyzeModel { model: string; provider: string; label: string; reason: string }
// 스테이징(보관됨)된 한 파일/입력 — 사용자가 [처리 시작]을 누르기 전까지 대기.
interface Staged { key: number; sourceId: number | null; name: string; hasText: boolean; status: "staging" | "staged" | "running" | "done" | "error" | "skip"; note?: string }

const extOf = (n: string) => n.toLowerCase().match(/\.([a-z0-9]+)$/)?.[1] ?? "";

// 업로드 원본을 연-월(YYYY-MM)로 묶어 최신순 트리로.
function groupByMonth(sources: SourceItem[]): [string, SourceItem[]][] {
  const m = new Map<string, SourceItem[]>();
  for (const s of sources) {
    const k = s.createdAt.slice(0, 7);
    const arr = m.get(k);
    if (arr) arr.push(s); else m.set(k, [s]);
  }
  return [...m.entries()].sort((a, b) => b[0].localeCompare(a[0]));
}

export default function MaterialsTab({ scope, hidden, onOpenWiki, dataRev, onDataChanged }: {
  scope: string; hidden?: boolean; onOpenWiki: (path: string) => void; modelsRev?: number; dataRev?: number; onDataChanged?: () => void;
}) {
  const [title, setTitle] = useState("");
  const [text, setText] = useState("");
  const [busy, setBusy] = useState(false); // [처리 시작] 진행 중(전체 직렬)
  const [err, setErr] = useState<string | null>(null);
  const [uploadMode, setUploadMode] = useState<"llm" | "raw">("llm"); // 처리 방식(확정 시 적용)
  const [staged, setStaged] = useState<Staged[]>([]); // 대기(스테이징)된 항목
  const [sources, setSources] = useState<SourceItem[]>([]);
  const [deleting, setDeleting] = useState<number | null>(null);
  const [delNote, setDelNote] = useState<string | null>(null);
  const [canManage, setCanManage] = useState(false); // 아카이브·영구삭제 권한(룸 관리자)
  const [archivedSources, setArchivedSources] = useState<SourceItem[]>([]);
  const [showArchived, setShowArchived] = useState(false);
  const [convertExts, setConvertExts] = useState<string[]>([]);
  const [policy, setPolicy] = useState<UploadPolicy | null>(null);
  const [analyzeModel, setAnalyzeModel] = useState<AnalyzeModel | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const [acting, setActing] = useState<Set<number>>(new Set()); // 분석/원본그대로 처리 중인 소스 id
  const [notes, setNotes] = useState<Record<number, string>>({}); // 처리 결과 메모(자동전환·반영 등)
  const fileRef = useRef<HTMLInputElement>(null);

  const load = useCallback(async () => {
    try {
      const res = await fetch(`/api/materials?scope=${encodeURIComponent(scope)}`, { cache: "no-store" });
      const d = await res.json();
      if (res.ok) {
        setSources(d.sources); setConvertExts(d.convertExts || []); setPolicy(d.policy || null);
        setCanManage(Boolean(d.canManage)); setAnalyzeModel(d.analyzeModel || null);
      }
    } catch { /* noop */ }
  }, [scope]);

  // 아카이브된 자료 목록(복원/영구삭제 뷰) — 별도 조회(?archived=1).
  const loadArchived = useCallback(async () => {
    try {
      const res = await fetch(`/api/materials?scope=${encodeURIComponent(scope)}&archived=1`, { cache: "no-store" });
      const d = await res.json();
      if (res.ok) setArchivedSources(d.sources || []);
    } catch { /* noop */ }
  }, [scope]);

  useEffect(() => { setSources([]); setStaged([]); setErr(null); setDelNote(null); setArchivedSources([]); setShowArchived(false); load(); }, [scope, load]);

  // 교차 갱신: 위키 배너에서 [AI로 분석]하거나 다른 경로로 데이터가 바뀌면 목록 재조회(초기 마운트는 건너뜀).
  const firstRev = useRef(true);
  useEffect(() => {
    if (firstRev.current) { firstRev.current = false; return; }
    load(); if (showArchived) loadArchived();
  }, [dataRev]); // eslint-disable-line react-hooks/exhaustive-deps

  async function openWiki(s: SourceItem) {
    try {
      const res = await fetch(`/api/materials/${s.id}/pages`);
      const d = await res.json();
      if (res.ok && d.paths?.length) onOpenWiki(d.paths[0]);
      else setDelNote(`「${s.title}」에서 생성된 위키 페이지를 찾지 못했습니다.`);
    } catch {
      setDelNote("위키 페이지를 찾지 못했습니다.");
    }
  }

  // 자료 아카이브(소프트 삭제) — 목록에서 숨기고 아카이브로. 원본·위키 페이지는 보존. 룸 관리자만.
  async function archiveSource(s: SourceItem) {
    if (!confirm(`원본 「${s.title}」을(를) 아카이브할까요?\n목록에서 숨겨지며, 아카이브에서 복원하거나 영구삭제할 수 있습니다. (위키 페이지는 그대로 유지됩니다)`)) return;
    setDeleting(s.id); setDelNote(null);
    try {
      const res = await fetch(`/api/materials/${s.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "archive" }) });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error || "아카이브에 실패했습니다.");
      setDelNote(`「${s.title}」 아카이브됨`);
      await Promise.all([load(), loadArchived()]);
    } catch (e) {
      setDelNote(`오류: ${e instanceof Error ? e.message : String(e)}`);
    } finally {
      setDeleting(null);
    }
  }

  // 아카이브에서 복원 — 다시 활성 목록으로.
  async function restoreSource(s: SourceItem) {
    setDeleting(s.id); setDelNote(null);
    try {
      const res = await fetch(`/api/materials/${s.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "restore" }) });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error || "복원에 실패했습니다.");
      setDelNote(`「${s.title}」 복원됨`);
      await Promise.all([load(), loadArchived()]);
    } catch (e) {
      setDelNote(`오류: ${e instanceof Error ? e.message : String(e)}`);
    } finally {
      setDeleting(null);
    }
  }

  // 영구삭제 — 원본·사이드카 제거 + 인용 위키 페이지에 '출처 소실' 표시. 되돌릴 수 없음.
  async function purgeSource(s: SourceItem) {
    if (!confirm(`원본 「${s.title}」을(를) 영구삭제할까요? 되돌릴 수 없습니다.\n매핑된 위키 페이지는 보존되며 '출처 소실' 표시가 남습니다.`)) return;
    setDeleting(s.id); setDelNote(null);
    try {
      const res = await fetch(`/api/materials/${s.id}`, { method: "DELETE" });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error || "삭제에 실패했습니다.");
      setDelNote(`「${s.title}」 영구삭제됨 · 위키 ${d.annotated}곳에 출처 소실 표시`);
      await Promise.all([load(), loadArchived()]);
      onDataChanged?.(); // 위키 페이지에 흔적 → 트리/리더 갱신
    } catch (e) {
      setDelNote(`오류: ${e instanceof Error ? e.message : String(e)}`);
    } finally {
      setDeleting(null);
    }
  }

  // 파일 선택/드롭 → ★스테이징만★(자동 처리 안 함). 사용자가 모드 고르고 [처리 시작]을 눌러야 인제스트.
  function onPickFile(e: React.ChangeEvent<HTMLInputElement>) {
    const files = e.target.files ? [...e.target.files] : [];
    e.target.value = "";
    if (files.length) void stageFiles(files);
  }
  function onDrop(e: React.DragEvent) {
    e.preventDefault();
    setDragOver(false);
    const files = e.dataTransfer?.files ? [...e.dataTransfer.files] : [];
    if (files.length) void stageFiles(files);
  }

  // 스테이징 결과 해석: 중복/미분석은 더 처리할 수 없으니 'skip'(완료), 그 외는 'staged'(처리 대기).
  function toStaged(prev: Staged, data: { status?: string; sourceId?: number; hasText?: boolean; unanalyzed?: boolean }): Staged {
    if (data.status === "SKIPPED_DUP") return { ...prev, status: "skip", note: "중복(건너뜀)" };
    if (data.unanalyzed || !data.sourceId) return { ...prev, status: "skip", note: "원본 보존(미분석)" };
    return { ...prev, status: "staged", sourceId: data.sourceId, hasText: !!data.hasText };
  }

  // 파일을 스테이징(추출·보관만, 토큰 0). 허용 안 되는 확장자는 에러로 표시.
  async function stageFiles(files: File[]) {
    const allowExt = (n: string) => !policy || policy.exts.includes(extOf(n));
    const ok = files.filter((f) => allowExt(f.name));
    const blocked = files.filter((f) => !allowExt(f.name));
    setErr(null);
    const base = Date.now();
    setStaged((prev) => [
      ...prev,
      ...blocked.map((f, i) => ({ key: base + 9000 + i, sourceId: null, name: f.name, hasText: false, status: "error" as const, note: policy?.note || "지원하지 않는 형식" })),
      ...ok.map((f, i) => ({ key: base + i, sourceId: null, name: f.name, hasText: false, status: "staging" as const })),
    ]);
    const single = ok.length === 1 ? (title.trim() || undefined) : undefined;
    for (let i = 0; i < ok.length; i++) {
      const key = base + i;
      try {
        const fd = new FormData();
        fd.append("scope", scope);
        if (single) fd.append("title", single);
        fd.append("file", ok[i]);
        const res = await fetch("/api/materials", { method: "POST", body: fd }); // 모델 미전송 → 서버가 자동 모델 기준 게이팅
        const data = await res.json();
        if (!res.ok) { setStaged((p) => p.map((x) => (x.key === key ? { ...x, status: "error", note: data.error || "업로드 실패" } : x))); continue; }
        setStaged((p) => p.map((x) => (x.key === key ? toStaged(x, data) : x)));
      } catch (e) {
        setStaged((p) => p.map((x) => (x.key === key ? { ...x, status: "error", note: e instanceof Error ? e.message : String(e) } : x)));
      }
    }
    if (single) setTitle("");
  }

  // 직접 입력 텍스트를 스테이징(대기열에 추가).
  async function stageText() {
    if (busy || !text.trim()) return;
    setErr(null);
    const key = Date.now();
    const name = title.trim() || text.trim().split("\n")[0].slice(0, 40) || "직접 입력";
    setStaged((prev) => [...prev, { key, sourceId: null, name, hasText: true, status: "staging" }]);
    try {
      const res = await fetch("/api/materials", {
        method: "POST", headers: { "content-type": "application/json" },
        body: JSON.stringify({ scope, title: title.trim() || undefined, text }),
      });
      const data = await res.json();
      if (!res.ok) { setStaged((p) => p.map((x) => (x.key === key ? { ...x, status: "error", note: data.error || "추가 실패" } : x))); return; }
      setStaged((p) => p.map((x) => (x.key === key ? toStaged(x, data) : x)));
      setText(""); setTitle("");
    } catch (e) {
      setStaged((p) => p.map((x) => (x.key === key ? { ...x, status: "error", note: e instanceof Error ? e.message : String(e) } : x)));
    }
  }

  // 스테이징된 소스를 ★선택한 모드★로 처리. raw는 텍스트가 있을 때만, 없으면(PDF·이미지) 자동으로 llm.
  async function runProcess(sourceId: number, hasText: boolean): Promise<{ ok: boolean; note: string }> {
    const fellBack = uploadMode === "raw" && !hasText;
    const effMode = uploadMode === "raw" && hasText ? "raw" : "llm";
    const body = effMode === "raw" ? { mode: "raw" } : { mode: "llm" }; // llm은 모델 미지정 → 서버 자동 선택
    const res = await fetch(`/api/materials/${sourceId}/analyze`, {
      method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body),
    });
    const data = await res.json();
    if (!res.ok) return { ok: false, note: `처리 실패: ${data.error || ""}` };
    if (effMode === "raw") return { ok: true, note: "원본 그대로 추가됨 · 토큰 0" };
    const sw = data.fallback ? " · 백업 모델로 자동 전환됨" : "";
    const prefix = fellBack ? "텍스트 없음 → 분석함 · " : "";
    const base = data.status === "NEEDS_REVIEW" ? "검토 대기" : "분석 반영됨";
    return { ok: true, note: prefix + base + sw };
  }

  // [처리 시작] — 대기(staged) 항목을 순차 처리(위키는 단일 라이터). 끝나면 목록·트리 갱신.
  async function runStaged() {
    if (busy) return;
    const todo = staged.filter((s) => s.status === "staged" && s.sourceId);
    if (!todo.length) return;
    setBusy(true); setErr(null);
    for (const it of todo) {
      setStaged((p) => p.map((x) => (x.key === it.key ? { ...x, status: "running", note: uploadMode === "raw" ? "추가 중…" : "분석 중…" } : x)));
      const r = await runProcess(it.sourceId!, it.hasText);
      setStaged((p) => p.map((x) => (x.key === it.key ? { ...x, status: r.ok ? "done" : "error", note: r.note } : x)));
    }
    setBusy(false);
    await load();
    onDataChanged?.(); // 위키 트리/리더 갱신(③)
  }

  function clearStaged() { setStaged([]); }

  // 잔여(PENDING/FAILED) 복구 — 업로드 중 이탈 등으로 남은 항목을 현재 모드로 다시 처리.
  async function recover(s: SourceItem) {
    if (acting.has(s.id)) return;
    setActing((a) => new Set(a).add(s.id));
    setNotes((n) => { const c = { ...n }; delete c[s.id]; return c; });
    try {
      const r = await runProcess(s.id, !!s.hasText);
      setNotes((n) => ({ ...n, [s.id]: r.note }));
    } catch (e) {
      setNotes((n) => ({ ...n, [s.id]: `오류: ${e instanceof Error ? e.message : String(e)}` }));
    } finally {
      setActing((a) => { const c = new Set(a); c.delete(s.id); return c; });
      await load(); onDataChanged?.();
    }
  }

  // [AI로 분석] — '원본 그대로'/'미분석' 자료를 ★자동 모델★로 분석해 엔티티·개념에 반영(옛 raw 페이지는 서버가 대체).
  async function analyzeItem(s: SourceItem) {
    if (acting.has(s.id)) return;
    setActing((a) => new Set(a).add(s.id));
    setNotes((n) => { const c = { ...n }; delete c[s.id]; return c; });
    try {
      const res = await fetch(`/api/materials/${s.id}/analyze`, {
        method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ mode: "llm" }),
      });
      const data = await res.json();
      if (!res.ok) setNotes((n) => ({ ...n, [s.id]: `분석 실패: ${data.error || ""}` }));
      else {
        const sw = data.fallback ? " · 백업 모델로 자동 전환됨" : "";
        setNotes((n) => ({ ...n, [s.id]: (data.status === "NEEDS_REVIEW" ? "검토 대기" : "AI 분석 반영됨") + sw }));
      }
    } catch (e) {
      setNotes((n) => ({ ...n, [s.id]: `오류: ${e instanceof Error ? e.message : String(e)}` }));
    } finally {
      setActing((a) => { const c = new Set(a); c.delete(s.id); return c; });
      await load(); onDataChanged?.(); // 새 엔티티/개념 페이지 → 위키 트리/리더 갱신
    }
  }

  const provider = analyzeModel?.provider;
  const external = uploadMode === "llm" && (provider === "gemini" || provider === "openai-compat");
  const procCount = staged.filter((s) => s.status === "staged" && s.sourceId).length;
  const accept = policy?.accept ?? (".md,.markdown,.txt,.csv,.html,.htm,.json,.pdf,.docx,.doc,.xlsx,.xls,.pptx,.odt,.ods,.odp,.rtf,.hwp,.hwpx,.png,.jpg,.jpeg,.gif,.webp" + convertExts.map((e) => `,.${e}`).join(""));

  return (
    <div className={`mat-wrap${hidden ? " hidden" : ""}`}>
      <div className="mat-col mat-col-upload">
        <div className="mat-card">
          <div className="mat-card-head"><IconUpload size={15} />자료 추가</div>
          <p className="mat-desc">
            올리면 먼저 <b>대기 목록</b>에 담깁니다. 처리 방식을 고르고 <b>[처리 시작]</b>을 눌러야 위키에 반영됩니다. 원본은 항상 그대로 보관됩니다.
          </p>

          {/* 처리 방식 선택 — 분석(엔티티·개념 연결) vs 원본 그대로(토큰 0 보관) */}
          <div className="mat-mode">
            <button type="button" className={`mat-mode-btn${uploadMode === "llm" ? " on" : ""}`} disabled={busy} onClick={() => setUploadMode("llm")}>
              분석해서 추가<span className="mat-mode-sub">엔티티·개념에 반영 · 다른 자료와 연결</span>
            </button>
            <button type="button" className={`mat-mode-btn${uploadMode === "raw" ? " on" : ""}`} disabled={busy} onClick={() => setUploadMode("raw")}>
              원본 그대로 추가<span className="mat-mode-sub">topics에 그대로 보관 · 토큰 0 · 연결 안 됨</span>
            </button>
          </div>

          {/* 분석 모델은 ★자동 선택★ — 사용자가 고르지 않는다. ⓘ 툴팁에 사유. */}
          {uploadMode === "llm" && analyzeModel && (
            <div className="mat-automodel" title={analyzeModel.reason}>
              <IconSparkles size={13} />
              <span>분석 모델 <b>{analyzeModel.label}</b> 자동 선택</span>
              <IconInfoCircle size={13} className="mat-automodel-info" />
            </div>
          )}

          {uploadMode === "raw" && (
            <div className="mat-switch-note"><IconArrowsExchange size={13} />
              <span>분석 없이 원본을 그대로 위키에 보관합니다(<b>토큰 0</b>). 엔티티·개념엔 정리되지 않으니, 연결이 필요하면 <b>분석해서 추가</b>를 쓰거나 나중에 목록에서 <b>AI로 분석</b>을 누르세요. (텍스트 없는 PDF·이미지는 자동으로 분석됩니다.)</span>
            </div>
          )}

          {external && (
            <div className="gemini-warn"><IconAlertTriangle size={13} />
              <span>{provider === "gemini"
                ? <>Gemini(외부)는 빠르지만 <b>올린 자료가 Google로 전송·학습</b>됩니다. <br />민감 자료는 올리지 마세요.</>
                : <>이 모델(외부)은 빠르지만 <b>올린 자료가 외부 서버로 전송</b>됩니다. <br />민감 자료는 올리지 마세요.</>}</span>
            </div>
          )}

          <div className={`mat-drop${busy ? " busy" : ""}${dragOver ? " dragover" : ""}`}
            onClick={() => { if (!busy) fileRef.current?.click(); }}
            onDragOver={(e) => { e.preventDefault(); if (!busy) setDragOver(true); }}
            onDragLeave={() => setDragOver(false)}
            onDrop={onDrop}>
            <IconUpload size={20} />
            <span><b>{policy?.textOnly ? "텍스트 파일(.txt·.md)을 끌어다 놓거나" : "파일을 끌어다 놓거나"}</b> 클릭해 선택 <span className="mat-multi">(여러 개 가능 · 대기 목록에 담김)</span></span>
            <input ref={fileRef} type="file" hidden multiple disabled={busy} accept={accept} onChange={onPickFile} />
          </div>
          <div className={`mat-formats${policy?.textOnly ? " mat-formats-note" : ""}`}>
            {policy?.note ?? "지원 형식: 텍스트(.md .txt) · PDF · 이미지 · 한글 · Word · Excel · PowerPoint · 오픈오피스 · RTF · HTML"}
          </div>

          <div className="mat-or">또는 직접 입력</div>
          <input className="mat-input" placeholder="제목 (단건 업로드/직접 입력 시, 비우면 자동)" value={title} maxLength={80} onChange={(e) => setTitle(e.target.value)} />
          <textarea className="mat-input mat-textarea" placeholder="여기에 내용을 붙여넣으세요…" value={text} onChange={(e) => setText(e.target.value)} />
          <button className="mat-stage-add" onClick={stageText} disabled={busy || !text.trim()}>대기 목록에 추가</button>

          {/* 대기(스테이징) 목록 */}
          {staged.length > 0 && (
            <div className="mat-queue">
              <div className="mat-queue-head">대기 {staged.filter((u) => u.status === "done" || u.status === "skip").length}/{staged.length} 처리됨</div>
              {staged.map((u) => {
                const cls = u.status === "running" || u.status === "staging" ? "running" : u.status === "error" ? "error" : u.status === "staged" ? "pending" : "done";
                const label = u.status === "staging" ? "올리는 중…" : u.status === "staged" ? "대기" : u.status === "running" ? (u.note || "처리 중…") : u.status === "error" ? `실패: ${u.note || ""}` : (u.note || "완료");
                return (
                  <div key={u.key} className={`mat-queue-item ${cls}`}>
                    <span className="mq-dot" />
                    <span className="mq-name" title={u.name}>{u.name}</span>
                    <span className="mq-status">{label}</span>
                  </div>
                );
              })}
            </div>
          )}

          {err && <div className="mat-banner err"><IconAlertTriangle size={14} />{err}</div>}

          <button className="mat-submit" onClick={runStaged} disabled={busy || procCount === 0}>
            {busy ? <><IconClockHour4 size={14} />{uploadMode === "raw" ? "추가 중…" : "분석 중…"}</> : (
              procCount === 0 ? "처리 시작 (대기 항목 없음)" : `${uploadMode === "raw" ? "원본 그대로 추가" : "분석해서 추가"} (${procCount}개)`
            )}
          </button>
          {staged.length > 0 && !busy && (
            <button className="mat-stage-clear" onClick={clearStaged}>대기 목록 비우기</button>
          )}
        </div>
      </div>

      <div className="mat-col mat-col-list">
        <div className="mat-card">
          <div className="mat-card-head"><IconFileText size={15} />최근 자료 {sources.length > 0 && `(${sources.length})`}</div>
          {delNote && <div className="mat-banner muted" style={{ marginBottom: 10 }}>{delNote}</div>}
          {sources.length === 0 ? (
            <p className="mat-desc">아직 올린 자료가 없습니다.</p>
          ) : (
            <div className="mat-tree">
              {groupByMonth(sources).map(([ym, items]) => (
                <SourceGroup key={ym} ym={ym} items={items} onArchive={archiveSource} onWiki={openWiki}
                  onRecover={recover} onAnalyze={analyzeItem} analyzeReason={analyzeModel?.reason}
                  deleting={deleting} acting={acting} notes={notes} canManage={canManage} />
              ))}
            </div>
          )}

          {/* 아카이브(소프트 삭제) 섹션 — 룸 관리자만. 펼칠 때 조회. */}
          {canManage && (
            <div className="mat-archive">
              <button className="mat-archive-head" onClick={() => { const n = !showArchived; setShowArchived(n); if (n) loadArchived(); }}>
                <IconChevronRight size={13} className={`tree-caret${showArchived ? " open" : ""}`} />
                <IconArchive size={14} />아카이브{archivedSources.length > 0 ? ` (${archivedSources.length})` : ""}
              </button>
              {showArchived && (
                archivedSources.length === 0 ? (
                  <p className="mat-desc mat-archive-empty">아카이브된 자료가 없습니다.</p>
                ) : (
                  <div className="mat-tree">
                    {groupByMonth(archivedSources).map(([ym, items]) => (
                      <SourceGroup key={ym} ym={ym} items={items} archivedMode canManage={canManage}
                        onArchive={archiveSource} onWiki={openWiki} onRecover={recover} onAnalyze={analyzeItem}
                        onRestore={restoreSource} onPurge={purgeSource}
                        deleting={deleting} acting={acting} notes={notes} />
                    ))}
                  </div>
                )
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

