}, [aiBusy, aiInstr, scope]);

const tree = buildTree(files, wikiScope);
const labelOf = (p: string) => (p.split("/").pop() || p).replace(/\.md$/i, "");
const isArchivedPath = (p: string) => p.includes("/.archive/"); // 아카이브된 페이지 열람 중인지

return (
  <div className={`wikitab${hidden ? " hidden" : ""}`}>
    <div className="wt-tree">
      <div className="wt-tree-head"><IconBook2 size={14} />위키 구조 {files.length > 0 && `(${files.length})`}</div>
      {files.length === 0 ? (
        <div className="wt-empty">아직 위키 페이지가 없습니다. ‘자료’ 탭에서 문서를 올리면 생성됩니다.</div>
      ) : (
        <div className="wt-tree-body">
          {sortedChildren(tree).map((c) => (
            <TreeItem key={c.name} node={c} depth={0} selected={active} onSelect={openPage} types={types} />
          ))}
        </div>
      )}
      {/* 아카이브(삭제) 섹션 — 룸 관리자만, 아카이브된 페이지가 있을 때 */}
      {canManage && archived.length > 0 && (
        <div className="wt-archive">
          <button className="wt-archive-head" onClick={() => setShowArchive((o) => !o)}>
            <IconChevronRight size={13} className={`tree-caret${showArchive ? " open" : ""}`} />
            <IconArchive size={14} />아카이브 ({archived.length})
          </button>

                onDragLeave={() => setDragOver((d) => (d === p ? null : d))}
                onDrop={(e) => { e.preventDefault(); if (dragPath.current) reorderTab(dragPath.current, p); dragPath.current = null; setDragOver(null); }}
                onDragEnd={() => { dragPath.current = null; setDragOver(null); }}
              >
                <button className="wt-tab-label" onClick={() => setActive(p)}>{labelOf(p)}</button>
                <button className="wt-tab-close" onClick={() => closeTab(p)} aria-label="탭 닫기"><IconX size={11} /></button>
              </div>
            ))}
          </div>
        )}
        {tabs.length === 0 ? (
          <div className="wt-reader-empty">
            <IconFileText size={22} />
            <span>왼쪽에서 페이지를 선택하세요. 본문의 <span className="md-link">파란 링크</span>를 누르면 그 페이지가 새 탭으로 열립니다.</span>
          </div>
        ) : (
          // ★열린 탭을 모두 렌더하고 active만 표시★ — 각 탭의 DOM(스크롤)이 유지돼 전환해도 스크롤 보존.
          tabs.map((p) => {
            const pg = pages[p];
            const loading = loadingPaths.has(p) || !pg;
            return (
              <div key={p} className="wt-reader-body" style={{ display: active === p ? undefined : "none" }}>
                <div className="wt-reader-head">
                  <span className="wt-reader-path">{p}</span>
                  {isArchivedPath(p) ? (
                    // 아카이브된 페이지 열람 — 읽기 전용 + 복원/영구삭제(관리자만)
                    <>
                      <span className="wt-arch-badge"><IconArchive size={12} />아카이브됨 · 질의에서 제외</span>
                      {canManage && (
                        <button className="wt-edit" onClick={() => archiveAction(p, "restore")} disabled={busy} title="이 페이지를 복원">
                          <IconArrowBackUp size={13} />복원
                        </button>
                      )}
                      {canManage && (
                        <button className="wt-del" onClick={() => archiveAction(p, "delete")} disabled={busy} title="이 페이지를 영구삭제">
                          <IconTrashX size={13} />영구삭제
                        </button>
                      )}
                    </>
                  ) : (
                    <>
                      {editing !== p && scope.startsWith("project-") && (
                        <button className="wt-promote" onClick={() => requestPromote(p)} disabled={promoting}>
                          <IconArrowUp size={13} />{promoNote || (promoting ? "요청 중…" : "공통으로 승격 요청")}
                        </button>
                      )}
                      {editing !== p && canManage && (
                        <button className="wt-edit" onClick={() => startEdit(p)} disabled={!pg} title="이 페이지를 편집">
                          <IconPencil size={13} />편집
                        </button>
                      )}
                      {editing !== p && canManage && (
                        <button className="wt-del" onClick={() => archiveAction(p, "archive")} disabled={busy} title="이 페이지를 아카이브(삭제)">
                          <IconTrash size={13} />삭제(아카이브)
                        </button>
                      )}
                    </>
                  )}
                </div>
                {pg && pg.sources.length > 0 && (
                  <div className="wt-origin">
                    <div className="wt-origin-head">원본 자료 ({pg.sources.length}) — 이 위키 페이지의 출처</div>
                    <div className="wt-origin-list">
                      {pg.sources.map((s) => {
                        const FI = typeIcon(s.type);
                        return (
                          <a key={s.id} className="wt-origin-item" href={`/api/materials/${s.id}/raw`} target="_blank" rel="noreferrer" title="원본 열기">
                            <FI size={15} />
                            <span className="wt-origin-title">{s.title}</span>
                            <span className="wt-origin-type">{s.type}</span>
                            <IconExternalLink size={13} />
                          </a>
                        );
                      })}
                    </div>
                    {pg.sources.some((s) => s.type === "IMAGE") && (
                      <div className="wt-images">
                        {pg.sources.filter((s) => s.type === "IMAGE").map((im) => (
                          <a key={im.id} href={`/api/materials/${im.id}/raw`} target="_blank" rel="noreferrer" title={im.title}>
                            <img src={`/api/materials/${im.id}/raw`} alt={im.title} />
                          </a>
                        ))}
                      </div>
                    )}
                  </div>
                )}
                {editing === p && !isArchivedPath(p) ? (
                  <div className="wt-editor">
                    <div className="wt-ai-row">
                      <input className="wt-ai-input" value={aiInstr} onChange={(e) => setAiInstr(e.target.value)}
                        placeholder="AI에게 수정 지시 (예: 오래된 수치 갱신, 표로 정리)" disabled={aiBusy}
                        onKeyDown={(e) => { if (e.key === "Enter") aiEdit(p); }} />
                      <button className="wt-ai-btn" onClick={() => aiEdit(p)} disabled={aiBusy || !aiInstr.trim()}>
                        <IconSparkles size={13} />{aiBusy ? "수정 중…" : "AI로 수정"}
                      </button>
                    </div>
                    <textarea className="wt-editor-ta" value={draft} onChange={(e) => setDraft(e.target.value)} spellCheck={false} />
                    <div className="wt-editor-acts">
                      <button className="wt-save" onClick={() => savePage(p)} disabled={saving}>{saving ? "저장 중…" : "저장"}</button>
                      <button className="wt-cancel" onClick={cancelEdit} disabled={saving}>취소</button>
                      {editNote && <span className="wt-edit-note">{editNote}</span>}
                    </div>
                  </div>
                ) : (
                  <div className="wt-md">{loading ? "불러오는 중…" : renderMarkdown(pg!.content, onLink)}</div>
                )}
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}

